  --ig-label-char-width: 6.6px;
  --ig-focus-ring: 2px;
  --ig-space-micro: 2px;
  --ig-space-snug: 8px;
  --ig-space-loose: 16px;
  --ig-space-wide: 20px;
  --ig-radius-small: 4px;
  --ig-radius-large: 14px;
  --ig-row-min-height: 44px;
  --ig-row-padding-block: 13px;
  --ig-band-rail: 3px;
  --ig-rank-column: 34px;
  --ig-row-height-dense: 56px;
  --ig-row-padding-block-dense: 8px;
  --ig-rank-column-dense: 30px;
  --ig-row-title-line: 20px;
  --ig-row-meta-line: 20px;
  --ig-row-line-gap: 0px;
  --ig-station-box: 26px;
  --ig-card-line: 18px;
  --ig-panel-title-line: 20px;
  --ig-tint-fill: 8%;
  --ig-tint-border: 30%;
  --ig-tint-wash: 5%;
