.ig-ladder {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  line-height: var(--ig-line-height);
  color: var(--ig-text-body);
}

.ig-ladder-search {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

.ig-ladder-search input {
  background: var(--ig-surface);
  color: var(--ig-text);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
}

.ig-ladder-search input:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

.ig-ladder-match {
  display: flex;
  gap: var(--ig-space-tight);
  align-items: baseline;
}

.ig-chip {
  align-self: flex-start;
  background: var(--ig-surface-2);
  color: var(--ig-text-body);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight) var(--ig-space);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  cursor: pointer;
}

.ig-chip:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

.ig-chip[aria-expanded='true'] {
  border-color: var(--ig-accent);
  color: var(--ig-text);
}

/* THE LIST ITEM IS A GRID CELL AND NOTHING ELSE. It deliberately does not
   carry .ig-capsule: that is layer 1's own card, and a card inside a card put
   the stuck tint and the hover on the inner border only. */
.ig-capsule-cell {
  display: flex;
  min-width: 0;
}

/* THE BOARD'S BOX DRAWS NO GROUND AND NO BORDER (issue 296). Layer 1's
   refusal box paints the second fill, which is the group cards' own fill, so
   the cards vanished into it; the export's board sets its cards straight on
   the zone. Scoped to the ladder, so the viewer's own refusal keeps its box. */
.ig-ladder .ig-refusal {
  background: none;
  border: 0;
}

/* FOUR CARDS ACROSS A COLUMN, NOT FOUR ROWS DOWN IT. Frame 17f lays the
   capsules out as a board, which is what makes the counts comparable at a
   glance — the whole reason the count leads. minmax(0, 1fr) rather than a
   width, because this stylesheet declares no fixed length: a title is arbitrary
   and auto would let the longest one set every column. Scoped to the ladder's
   own cards, under a refusal or alone with nothing selected, so §16's
   single-column list, drawn from the same class in layer 1, is untouched. */
.ig-ladder .ig-groups {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--ig-space);
}

/* THE WHOLE CAPSULE IS THE CONTROL, so the button carries the card and the
   list item carries nothing. A button wrapping a card needs its own alignment
   and wrapping reset: a user agent centres and nowraps button content, and both
   are wrong for a four-part card with a title in it. */
.ig-capsule-enter {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: start;
  gap: var(--ig-space-tight) var(--ig-space);
  width: 100%;
  height: 100%;
  text-align: left;
  /* THE EXPORT'S GROUP CARD (issue 296): the second fill at the card corner,
     with no border. */
  background: var(--ig-surface-2);
  color: var(--ig-text-body);
  border: 0;
  border-radius: var(--ig-radius-large);
  padding: var(--ig-space);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  cursor: pointer;
}

.ig-capsule-enter:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

/* With no border to colour, a hovered card takes the stronger fill. */
.ig-capsule-enter:hover {
  background: var(--ig-surface);
}

/* A STUCK CARD SAYS SO ON ITS TAG ALONE (issue 296). It drew blocked-by's hue
   on its border and on its reach line as well, and the export's stuck group is
   the same card as any other with an error Loop tag in it: one state, one mark.
   data-reach stays on the markup for a host that wants to style the stuck card. */

/* THE COUNT LEADS BY ITS PLACE AND ITS INK, NOT ITS FACE. It is a count, and
   every count both packages draw is the body sans at the body size with
   tabular figures (#254), so a column of capsule counts still lines up down the
   board. It was the rank face and size; a rank is a position in the order, which
   a capsule's member count is not. It stays first in the card and at full
   text colour, which is what makes it the part read first. */
.ig-capsule-size {
  grid-column: 1;
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  font-variant-numeric: tabular-nums;
  /* Medium, as the export's group count "38 issues" is (#254 design read). */
  font-weight: var(--ig-weight-medium);
  color: var(--ig-text);
}

/* NO BLOCKED COUNT (issue 296): the export's group card draws none, so the
   chip that held it, and its rule, are gone. */

/* THE CYCLE IS A TAG IN THE ERROR STATE, as the export draws its loop tag: the
   small role in the sans at medium weight, the failed state's colour on the
   failed state's own fill, at the end of the count's row. The theme carries no pill radius, so the corner is the large radius,
   which rounds a tag this tall fully. The fill is the theme's error fill since
   issue 293, so a host maps it to its own; it was the state colour mixed at
   the chip tint, which no host role could name. The tag is the wide space
   step tall, as layer 1's tag is. */
.ig-capsule-loop {
  grid-column: 2;
  justify-self: end;
  align-items: center;
  display: inline-flex;
  background: var(--ig-state-failed-fill);
  block-size: var(--ig-space-wide);
  border-radius: var(--ig-radius-large);
  padding: 0 var(--ig-space-snug);
  color: var(--ig-state-failed);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  font-weight: var(--ig-weight-medium);
  white-space: nowrap;
}

/* THE NAME AND THE REACH SPAN BOTH COLUMNS, and the name is the one part
   allowed to wrap: a title is arbitrary length, and letting it size the grid
   would make every card on the board a different shape. */
/* IN MUTED INK (issue 296), as the export's group card sets its "Around …"
   line: the count above it is the part read first. */
.ig-capsule-name {
  grid-column: 1 / -1;
  color: var(--ig-text-muted);
  min-width: 0;
  overflow-wrap: anywhere;
}

.ig-capsule-reach {
  grid-column: 1 / -1;
  color: var(--ig-text-muted);
  font-size: var(--ig-font-size-small);
  font-variant-numeric: tabular-nums;
}

/* A PANEL, NOT A LOOSE COLUMN OF TEXT. With the control moved to the rail
   footer (§17a) this wrapper was left holding an unstyled ol at zero inset:
   it began hard against the zone's own rule, ran on from the graph above it
   with nothing between them, and read as content that had escaped a container
   rather than as the thing the reader had just asked to see.

   THE TOP RULE AND THE PADDING ARE THE CANVAS TOOLBAR'S, because this is the
   same kind of band one row lower — a full-bleed section of the canvas zone,
   not a card floating on it. --ig-bg for the same reason the toolbar takes
   it: the ground this zone already paints, so the two read as one surface. */
.ig-ladder-isolated {
  border-top: var(--ig-stroke) solid var(--ig-line);
  padding: var(--ig-space) var(--ig-space-wide);
}

/* A SECTION HEAD IN THE READ-OUT VOICE the canvas caption and the rail footer
   count already use on this surface — mono, micro, muted, tracked — because it
   carries the same kind of fact and a heavier treatment would make a list of
   issues nobody has to act on the loudest thing in the zone. */
.ig-isolated-caption {
  margin: 0 0 var(--ig-space-tight);
  color: var(--ig-text-muted);
  font-family: var(--ig-font-mono);
  font-size: var(--ig-font-size-micro);
  letter-spacing: var(--ig-tracking-group);
  text-transform: uppercase;
}

.ig-isolated-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
}

/* A ROW PER ENTRY, WITH A GAP THE MARKUP DOES NOT SUPPLY. The element helper
   concatenates its children with no whitespace, so the key and the title
   rendered as one run of text — #492Audit log pagination. Latent until §17a
   moved the CONTROL to the rail footer and made this list the thing a reader is
   sent to, rather than a chip's afterthought. */
/* SEPARATED THE WAY EVERY OTHER LIST OF ISSUES ON THIS SURFACE IS, with a
   hairline between rows rather than a gap between them. A gap left five lines
   of text floating in a column; the rule is what makes them read as rows, and
   it is the treatment the viewer's own order rows already carry. Last row
   included would double the zone's next edge, so it stops one short. */
.ig-isolated-list li {
  display: flex;
  gap: var(--ig-space-tight);
  align-items: baseline;
  min-width: 0;
  padding: var(--ig-space-tight) 0;
}

.ig-isolated-list li + li {
  border-top: var(--ig-stroke) solid var(--ig-line);
}

/* THE KEY IN ITS OWN COLUMN, so five titles start on one edge rather than
   wherever their number happened to end. tabular-nums and a measure in
   characters are what the capsule's own count line already uses for the same
   reason: a ragged left edge on a column of ids reads as a mistake. An issue
   number is read, not copied, so it is the sans layer 1 gives it, not mono;
   the smaller size is this list's own, a column beside the titles. */
.ig-isolated-list .ig-id {
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  font-variant-numeric: tabular-nums;
  color: var(--ig-text-muted);
  flex: none;
  min-inline-size: calc(var(--ig-char-width) * 5);
}

/* The title carries the row, so it takes the body colour and wraps rather than
   setting the row's width — the rule .ig-capsule-name states one file up. */
.ig-isolated-list .ig-title {
  color: var(--ig-text);
  min-width: 0;
  overflow-wrap: anywhere;
}


.ig-overlay {
  pointer-events: none;
}

.ig-overlay-halo {
  fill: none;
  stroke: var(--ig-focus);
  stroke-linecap: round;
}

/* The stroke is set per element from the treatment table — a state's own hue
   where it has one, the relationship's where it does not — for the same reason
   the viewer sets its dash per element: one source for a channel. */
.ig-overlay-dash {
  fill: none;
}

.ig-overlay-marching {
  stroke-dasharray: 4 4;
  animation: ig-overlay-march 1s linear infinite;
}

.ig-overlay-dotted {
  stroke-dasharray: 1 3;
}

@keyframes ig-overlay-march {
  to {
    stroke-dashoffset: -8;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ig-overlay-marching {
    animation: none;
  }
}

/* QUALIFIED, AND THE QUALIFICATION IS THE WHOLE RULE — it is what makes these
   three declarations apply at all.

   They used to be bare, and the comment here explained why: a together-with was
   drawn as a CONNECTOR rather than an edge path, so an edge-anchored rule left
   one of the five relationships unstyled. Both halves of that have since stopped
   being true, and nothing noticed either.

   The connector is gone — layer 1's section-16 pass draws a together unit as ONE
   card with its members listed inside, so the relationship's whole drawn form is
   its badge, and the badge rules below are what reach it.

   And the bare selector never painted an edge. A drawn path carries BOTH the edge
   class with its kind attribute, which the viewer hues at specificity (0,2,0), and
   the state attribute, which at (0,1,0) loses to it — and specificity beats source
   order, so concatenating this sheet last changed nothing. Measured in a browser:
   a conflicted blocked-by edge computed the relationship's own red, never the
   state's gold.

   So the bare rules matched exactly two kinds of element and were dead on both.
   On a path they lost the cascade; on a badge they set a stroke, which a span has
   no use for.

   invalid was the only state that looked right, and by accident: it is the one
   settled state carrying a dash, so render.ts builds a CLONE for it, and a clone
   drops its class — which is precisely why that file sets the stroke inline on
   one. The states that build no clone had nothing to fall back on, which is why
   failed rendered identically to invalid, and conflict identically to a settled
   edge.

   The kind attribute is carried by every drawn path and by nothing else, so adding
   it reaches (0,3,0) and wins OUTRIGHT rather than by tying and being placed later.
   A tie would work today and would break the first time a host reordered the
   sheets — and this rule has already failed silently once.

   (No backticks in here: this is inside a template literal, and one ends it.) */
.ig-edge[data-edge][data-ig-state~='invalid'] {
  stroke: var(--ig-state-invalid);
}

.ig-edge[data-edge][data-ig-state~='failed'] {
  stroke: var(--ig-state-failed);
}

.ig-edge[data-edge][data-ig-state~='conflict'] {
  stroke: var(--ig-state-conflict);
}

/* A BADGE IS NOT A STROKE, AND SOME RELATIONSHIPS ARE ONLY A BADGE.
   together-with is drawn as no line at all — it shares a rank rather than
   ordering anything, and layer 1 draws the unit as one card with its members
   listed inside — so the chip that names it is its entire representation. The
   marks this module clones from a stroke cannot be cloned from a span, and the
   stroke rules above paint a property a span does not have: an in-flight or
   refused together-edge therefore read exactly like a settled one, with the
   state visible only to a screen reader.

   So a chip states the state with what a chip HAS: an outline and its ink.
   Every state the drawn edge distinguishes, distinguished here too — including
   the two that have no hue of their own, where a stroke uses a ghost or a halo
   and a chip uses a dash and the focus ring.

   AN OUTLINE, NOT A BORDER, since layer 1 drew a relationship as muted words
   with no border at all (issue 293). A border colour on a chip with no border
   paints nothing, so a pending write read exactly like a settled one; an
   outline takes no room, so the words do not move when a state arrives. */
.ig-badge[data-ig-state~='invalid'] {
  color: var(--ig-state-invalid);
  outline: var(--ig-stroke) solid var(--ig-state-invalid);
}

.ig-badge[data-ig-state~='failed'] {
  color: var(--ig-state-failed);
  outline: var(--ig-stroke) solid var(--ig-state-failed);
}

.ig-badge[data-ig-state~='conflict'] {
  color: var(--ig-state-conflict);
  outline: var(--ig-stroke) solid var(--ig-state-conflict);
}

/* Pending is the state with no hue: the drawn edge says it with a dashed ghost,
   and a chip says it with a dashed outline of its own. Style and width only,
   so the outline takes the chip's own ink, or the hue of a state above that
   it shares, the way the border it replaced did. */
.ig-badge[data-ig-state~='pending-write'] {
  outline-style: dashed;
  outline-width: var(--ig-stroke);
}

/* Selected is the focus ring's meaning, and the theme says so where it declares
   the token — selected is deliberately not an edit-state hue. */
.ig-badge[data-ig-state~='selected'] {
  box-shadow: 0 0 0 var(--ig-stroke) var(--ig-focus);
}

.ig-overlay-chip {
  background: var(--ig-surface-2);
  color: var(--ig-text-muted);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
}

.ig-overlay-cross {
  color: var(--ig-state-failed);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
}

.ig-overlay-reason {
  color: var(--ig-state-invalid);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
}

.ig-overlay-held {
  color: var(--ig-state-conflict);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
}


.ig-audit {
  align-items: center;
  display: inline-flex;
  font-family: var(--ig-font-ui);
  /* The body size, so the problems word reads at the size of its count: the
     export draws the whole button at one size. */
  font-size: var(--ig-font-size);
  gap: var(--ig-space-tight);
}

/* THE WORDS SIT ON ONE BASELINE (issue 293). An inline-flex box takes its
   baseline from its first item that takes part in baseline alignment, and
   centred items take none, so the empty dot leading the button gave it its
   bottom edge as a baseline and the count rode high beside the header's other
   text. The count and its word align by baseline, which makes the count the
   button's baseline; the dot alone is centred, below. */
.ig-audit-toggle {
  align-items: baseline;
  background: none;
  border: 0;
  border-radius: var(--ig-radius-small);
  color: var(--ig-text);
  cursor: pointer;
  display: inline-flex;
  font: inherit;
  gap: var(--ig-space-tight);
  padding: 0;
}

/* PRESSED WHILE ITS PANEL IS OPEN (issue 334, Design 6b8a53e): the secondary fill,
   as the order strip's button reads while its panel is open. */
.ig-audit-toggle[aria-expanded='true'] {
  background: var(--ig-surface-2);
}

/* THE WORDS ARE IN TEXT INK, as the export's state label is; only the
   neutral state reads muted, and a closed blocker is the neutral one. */
.ig-audit-toggle[data-ig-audit-worst='stale-blocker'] {
  color: var(--ig-text-muted);
}

/* A COUNT, SO BODY TEXT: the body sans at the body size, with tabular figures
   to hold its digits still. The mono face is for keys a reader copies, and a
   count is read as a number, not copied. */
.ig-audit-count {
  color: var(--ig-text);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  font-variant-numeric: tabular-nums;
}

/* THE DOT OF THE WORST PROBLEM, before the count, as the export's head draws
   its problems button (issue 293). The export's state dot is eight across; the
   snug step is eight. Its colour is the worst class's state, as the export's
   rules give each one: a loop is the error state, a duplicate of a closed issue
   and relationships that could not be read are the attention state, and a
   closed blocker is the neutral state, drawn as a ring because nothing is
   happening. The dot reads each state's MARK token, not its hue: a host maps
   the hue to the state's text ink, which on a light ground is near black, and
   the mark to the state's own colour. The pending station colour is the
   neutral ring. */
.ig-audit-dot {
  align-self: center;
  block-size: var(--ig-space-snug);
  border-radius: 50%;
  flex: none;
  inline-size: var(--ig-space-snug);
  /* With the toggle's gap, twelve between the dot and its count, as the
     export's state label spaces its dot. */
  margin-inline-end: var(--ig-space-tight);
}

.ig-audit-dot[data-ig-audit-worst='cycle'] {
  background: var(--ig-state-failed-mark);
}

.ig-audit-dot[data-ig-audit-worst='dead-duplicate-ref'],
.ig-audit-dot[data-ig-audit-worst='encoding-refused'] {
  background: var(--ig-state-conflict-mark);
}

.ig-audit-dot[data-ig-audit-worst='stale-blocker'] {
  box-shadow: inset 0 0 0 var(--ig-stroke) var(--ig-station-pending);
}

[data-ig-audit] {
  box-shadow: inset var(--ig-stroke-audit) 0 0 0 var(--ig-edge-serialize-with);
}

/* §17d'S PANEL. Note what it does NOT select on: data-ig-audit,
   whose rule immediately above is deliberately unqualified because it lands on a
   row the VIEWER rendered. A card wearing that attribute would draw the rail's
   gold bar whatever state it was drawn in. Cards carry data-ig-audit-kind. */
/* IT IS THE SELECTION'S PEER, NOT ITS HEADING, so it carries its own padding:
   it is a sibling of .ig-inspector inside the zone rather than a child, and
   that column's padding does not reach it.

   IT DECLARES NO SIZE OF ITS OWN, AND THAT IS THE LAYERING. Issue 177 gave the
   audit half the inspector column, scrolling itself past that — and since the
   fourth class moved to ./refused.ts the half belongs to the REGION holding both
   surfaces rather than to this panel. Either way it is a fact about SHARING A
   COLUMN, not a fact about the panel, so it is declared by the composition that
   owns the zone. See workspace/styles.ts.

   The difference is reachable rather than theoretical: renderAuditPanel and
   this stylesheet are both public exports, so a consumer can draw the panel
   outside renderWorkspace. Capping it there would hide findings behind an inner
   scrollbar with half the container left empty and no selection detail to
   reserve the space for. A leaf that sized itself would be wrong in every
   composition but one. */
.ig-audit-panel {
  border-bottom: var(--ig-stroke) solid var(--ig-line);
  display: flex;
  flex-direction: column;
  font-family: var(--ig-font-ui);
  gap: var(--ig-space-snug);
  min-height: 0;
  padding: var(--ig-space);
}

/* THE RING FOR THE PANEL'S OWN TAB STOP. Unscoped, unlike the sizing above,
   because the tabindex is in this leaf's MARKUP and is therefore carried into
   every composition: a focusable element that shows nothing on focus is a stop
   a keyboard reader lands on blind, wherever it is drawn.

   INSET, WHICH IS THE VIEWER'S OWN IDIOM for exactly this shape — its sheet
   draws every focus ring at a negative offset. Drawn outward it would sit on
   the panel's border box against the zone's edge and the column's own scroll,
   where the top and bottom of the ring are the first thing clipped. */
.ig-audit-panel:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: calc(var(--ig-focus-ring) * -1);
}

.ig-audit-panel-head {
  align-items: center;
  display: flex;
  gap: var(--ig-space-tight);
}

/* THE PANEL'S TITLE, AS THE EXPORT DRAWS IT: one heading, the count and then
   the host's words, in the sans at medium weight in text colour. It was an
   uppercase mono label in gold with the count beside it; content.md rules out
   that small uppercase label, and the count reads as part of the sentence it
   starts. The export's panel title is a step above the body, and since issue
   293 the theme carries that step and its line, so the title takes both. */
.ig-audit-panel-heading {
  color: var(--ig-text);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-panel-title);
  font-weight: var(--ig-weight-medium);
  line-height: var(--ig-panel-title-line);
  margin: 0;
}

/* The count inside the title is a count, so it keeps the sans and tabular
   figures, in the title's own ink and at the title's own size: the export sets
   the count and the words as one run, and a count a step smaller than the
   words it leads would put two sizes in one heading. */
.ig-audit-panel-count {
  color: inherit;
  font-family: var(--ig-font-ui);
  font-size: inherit;
  font-variant-numeric: tabular-nums;
}

/* NO CAP ON THE LIST, AND THAT IS STILL RIGHT — the bound belongs to the PANEL
   above, not here. Three caps were tried on this element (a fixed length, a
   share of a flex column, that share measured on the right box) and each was
   correct about the previous one's defect while the column stayed the thing
   that could not be bounded from in here. It still cannot: the list has no
   padding, so a scroll container here computes overflow-x to auto and clips the
   focus ring on every card control. The panel carries the share and the
   scrolling; see the rule above. */
.ig-audit-list {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-snug);
  list-style: none;
  margin: 0;
  padding: 0;
}

/* EACH FINDING IS THE EXPORT'S NOTE (issue 296): its state's icon beside its
   text, on a fill in its state at the control corner, padded, with no border.
   The neutral state, a closed blocker, sits on the second fill; a loop on the
   error fill and an unreadable relationship or a duplicate of a closed issue on
   the attention fill, each title and icon in its state's hue and the sentence
   under it in text ink. */
.ig-audit-card {
  align-items: flex-start;
  background: var(--ig-surface-2);
  border-radius: var(--ig-radius);
  display: flex;
  gap: var(--ig-space-snug);
  padding: var(--ig-space);
}

.ig-audit-note-text {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-micro);
  min-width: 0;
}

/* THE STATE'S ICON, AS THE EXPORT DRAWS IT: sixteen across, its stroke the
   theme's, in the note's own ink, set a step down so it sits on the title's
   first line. */
.ig-audit-icon {
  block-size: var(--ig-space-loose);
  color: var(--ig-text);
  fill: none;
  flex: none;
  inline-size: var(--ig-space-loose);
  margin-top: var(--ig-space-micro);
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: var(--ig-stroke);
}

.ig-audit-card[data-s='error'] .ig-audit-icon {
  color: var(--ig-state-failed);
}

.ig-audit-card[data-s='attention'] .ig-audit-icon {
  color: var(--ig-state-conflict);
}

.ig-audit-card[data-s='error'] {
  background: var(--ig-state-failed-fill);
}

.ig-audit-card[data-s='error'] .ig-audit-title {
  color: var(--ig-state-failed);
}

.ig-audit-card[data-s='attention'] {
  background: var(--ig-state-conflict-fill);
}

.ig-audit-card[data-s='attention'] .ig-audit-title {
  color: var(--ig-state-conflict);
}

.ig-audit-title {
  color: var(--ig-text);
  font-size: var(--ig-font-size);
  font-weight: var(--ig-weight-medium);
  margin: 0;
}

/* THE NOTE'S SENTENCE IS TEXT INK at the body size, as the export's note body
   is. It took --ig-text-body at a smaller step; muted stays out of it either
   way, because a finding's detail is a sentence. */
.ig-audit-detail {
  color: var(--ig-text);
  font-size: var(--ig-font-size);
  line-height: var(--ig-line-height);
  margin: 0;
}

/* 17d'S REMEDIES. A row of them under the card's sentence.

   THEY ARE QUIET CONTROLS DELIBERATELY. A remedy publishes a selection and
   never writes, so drawing it louder would promise an action it does not
   perform. 3's whole point is that the judgment stays
   with the owner, and a button styled like a commit invites a click that is
   not one.

   WRAPS, because a duplicate's card carries two of them inside a panel of fixed
   width whose cards also indent. A row that cannot wrap pushes its second
   control out of the panel, which is the shape the relationship row one sheet
   over already had to solve. (Worded around two particular verbs on purpose:
   acceptance scans this sheet's PROSE as well as its declarations for the
   vocabulary of a remedy that acts by itself, and it cannot tell a comment
   from a control. Both spellings of that idea are therefore unusable here,
   including in a note explaining why.)

   (The width itself is 3's number and lives in workspace/styles.ts, where the
   overlay is positioned. Naming it here would put a length in a sheet whose
   own guard reads comments as well as declarations - which is how this
   paragraph was first written, and caught.) */
.ig-audit-remedies {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ig-space-tight);
}

.ig-audit-remedy {
  /* An anchor too, for the open link on a loop with no drawn issue (300), so no underline. */
  text-decoration: none;
  background: none;
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius-small);
  color: var(--ig-text);
  cursor: pointer;
  font: inherit;
  font-size: var(--ig-font-size-meta);
  padding: var(--ig-space-micro) var(--ig-space-tight);
}

.ig-audit-remedy:hover {
  border-color: var(--ig-accent);
}

.ig-audit-remedy:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-micro);
}

/* 17d'S OWN ENTRY POINT - 'filter the rail to these' - in the panel head.

   IT SITS AT THE END OF THE HEAD ROW, after the count and the heading, which is
   where the frame draws it. margin-inline-start: auto rather than a width on
   the heading, so the head stays one flex row whatever the host's word is.

   aria-pressed IS STYLED, NOT JUST PUBLISHED. 2's ruling is that a filter
   which is visibly on, states what it hides and clears in one click is not a
   refusal - so 'visibly on' is a requirement here rather than a nicety. */
.ig-audit-filter {
  background: none;
  border: 0;
  border-radius: var(--ig-radius-small);
  color: var(--ig-text);
  cursor: pointer;
  font: inherit;
  font-size: var(--ig-font-size-meta);
  margin-inline-start: auto;
  padding: var(--ig-space-micro) var(--ig-space-tight);
}

/* A GHOST BUTTON, AS THE EXPORT DRAWS IT: no edge and no fill at rest, the
   second fill under the pointer, and when on, its words in the accent with
   still no edge. */
.ig-audit-filter:hover {
  background: var(--ig-surface-2);
}

.ig-audit-filter[aria-pressed='true'] {
  color: var(--ig-accent);
}

.ig-audit-filter:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-micro);
}

/* ---- §17d's fourth class: an unreadable relationship's note (./refused.ts) ----

   A NOTE IN THE PANEL SINCE ISSUE 296, styled as every note is above, its
   body sentence included; these rules draw only its two controls. */

/* ONE TREATMENT FOR BOTH CONTROLS, THOUGH ONE IS AN ANCHOR AND ONE A BUTTON.
   The element differs because what they DO differs — the link leaves the
   document and must say so to assistive technology — but they sit side by side
   in the frame as one pair of moves, and drawing them differently would imply a
   difference in weight that §17d does not make. */
.ig-audit-refused-open,
.ig-audit-refused-rewrite {
  align-items: center;
  background: none;
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius-small);
  color: var(--ig-text);
  cursor: pointer;
  display: inline-flex;
  font: inherit;
  font-size: var(--ig-font-size-meta);
  gap: var(--ig-space-micro);
  padding: var(--ig-space-micro) var(--ig-space-tight);
  text-decoration: none;
}

.ig-audit-refused-open:hover,
.ig-audit-refused-rewrite:hover {
  border-color: var(--ig-accent);
}

.ig-audit-refused-open:focus-visible,
.ig-audit-refused-rewrite:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-micro);
}

.ig-audit-refused-away {
  color: var(--ig-text-muted);
}


.ig-reevaluate {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  line-height: var(--ig-line-height);
  color: var(--ig-text-body);
}

/* Greyed one step, and never hidden: a stale order that is labelled is still
   the most useful thing on the screen.

   THE HUE TOKENS, NOT color, and that is the whole point of this rule. color
   on the rail greys almost nothing: the viewer's own stylesheet sets color
   directly on .ig-title, .ig-id and .ig-hold, and carries the stations
   and badges in background and border-color, none of which inherit at all.
   A specified value beats an inherited one, so the stale order would have kept
   its normal palette while this rule looked like it was doing something.

   Listing the descendants to override would go stale the first time layer 1
   colours something new. Custom properties DO inherit, so redefining the hue
   tokens here greys every descendant that reads one, a descendant added later
   included. It greys by colour, never by filter or opacity, so the rail's
   text keeps the contrast its theme pairs promise. styles.test.ts pins both
   halves: that layer 1 really does colour its own descendants, and that this
   rule redefines every hue and sets no bare color. */
.ig-reevaluate[data-order='held'] .ig-viewer {
  --ig-accent: var(--ig-text-muted);
  --ig-link: var(--ig-text-muted);
  --ig-link-hover: var(--ig-text-muted);
  --ig-focus: var(--ig-text-muted);
  --ig-station-ready: var(--ig-text-muted);
  --ig-station-pending: var(--ig-text-muted);
  --ig-station-held: var(--ig-text-muted);
  --ig-edge-blocked-by: var(--ig-text-muted);
  --ig-edge-serialize-with: var(--ig-text-muted);
  --ig-edge-together-with: var(--ig-text-muted);
  --ig-edge-duplicate-of: var(--ig-text-muted);
  --ig-edge-decomposed-from: var(--ig-text-muted);
  --ig-state-invalid: var(--ig-text-muted);
  --ig-state-failed: var(--ig-text-muted);
  --ig-state-conflict: var(--ig-text-muted);
  --ig-state-failed-fill: var(--ig-text-muted);
  --ig-state-failed-mark: var(--ig-text-muted);
  --ig-state-conflict-mark: var(--ig-text-muted);
  --ig-state-conflict-fill: var(--ig-text-muted);
  --ig-state-progress: var(--ig-text-muted);
}

.ig-order-computing {
  margin: 0;
  color: var(--ig-text-muted);
  font-size: var(--ig-font-size-small);
}

.ig-change-summary {
  display: flex;
  gap: var(--ig-space);
  align-items: baseline;
  flex-wrap: wrap;
}

.ig-change-line {
  display: flex;
  align-items: baseline;
}

/* THE SAVED LINE IS QUIET TEXT, counts included. It reports an edit the
   reader already made and stays until they dismiss it, so it must not compete
   with the order beside it. The count and its word carry their own colours
   because a rail chip draws them too, so inside the line both are named. */
.ig-change-line,
.ig-change-line .ig-change-count,
.ig-change-line .ig-change-word {
  color: var(--ig-text-muted);
}

/* The host's lead before the counts — the "Saved:" of "Saved: 2 moved". The
   line itself has no gap, so the space after the lead is this margin. */
.ig-change-saved {
  margin-inline-end: var(--ig-space);
}

.ig-change-parts {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  /* The blast radius reads as ONE line: "2 moved · 1 newly held". */
  gap: var(--ig-space-tight);
}

.ig-change-part {
  display: flex;
  gap: var(--ig-space-tight);
  align-items: baseline;
}

/* THE SEPARATOR IS GENERATED HERE, NOT WRITTEN INTO THE MARKUP, so the
   markup carries only the host's words. The empty alternative text after the
   slash keeps a screen reader from reading the dot aloud between facets. */
.ig-change-part + .ig-change-part::before {
  content: '·' / '';
}

/* A COUNT IS BODY TEXT: the body sans at the body size, with tabular figures
   so "2 moved" and "12 moved" keep their digits in one column. Mono is the
   face of a key a reader copies, and a count is read rather than copied. */
.ig-change-count {
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  font-variant-numeric: tabular-nums;
  color: var(--ig-text);
}

.ig-change-word {
  color: var(--ig-text-body);
}

.ig-change-unchanged {
  margin: 0;
}

.ig-change-dismiss {
  align-self: flex-start;
  background: var(--ig-surface-2);
  color: var(--ig-text-body);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight) var(--ig-space);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  cursor: pointer;
}

.ig-change-dismiss:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

.ig-delta-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

.ig-delta-chip {
  display: flex;
  gap: var(--ig-space-tight);
  align-items: baseline;
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight);
  background: var(--ig-surface-2);
}

.ig-delta-member {
  display: flex;
  gap: var(--ig-space-tight);
  align-items: baseline;
}

.ig-delta-key,
.ig-delta-ref {
  font-family: var(--ig-font-mono);
  color: var(--ig-text-muted);
}

/* The count and its word are adjacent spans with no text between them, so
   without this they render as 2up. Same reason .ig-change-part has one. */
.ig-delta-move {
  display: flex;
  gap: var(--ig-space-tight);
  align-items: baseline;
}

.ig-delta-move[data-direction='up'] .ig-change-count {
  color: var(--ig-station-ready);
}

.ig-delta-move[data-direction='down'] .ig-change-count {
  color: var(--ig-text-muted);
}

.ig-delta-readiness[data-readiness='promoted'] {
  color: var(--ig-station-ready);
}

.ig-delta-readiness[data-readiness='newly-held'] {
  color: var(--ig-station-held);
}

.ig-delta-presence {
  color: var(--ig-text-muted);
}

/* THE PLACED CHIP IS NOT A LIST ITEM and does not lay out like one: it sits at
   the end of its row, after whatever the row already drew, and it never grows
   the row's height on its own.

   WHAT PUTS IT AT THE TRAILING EDGE IS NOT HERE, and this comment claimed it
   was. It named margin-inline-start: auto, which an earlier revision of this
   rule did set and this one does not — the ranked row reaches the edge by
   being given a third grid column in workspace/styles.ts instead, and the
   footer row, which is a flex box rather than that grid, is pushed there by a
   rule of its own beside it. Both live with the row shapes they are about;
   what is left here is only what a placed chip looks like whatever it sits in.
   The claim survived the change that falsified it, which is this codebase's
   named failure mode and not a new one. */
.ig-delta-chip[data-placed] {
  display: inline-flex;
  gap: var(--ig-space-tight);
  align-items: baseline;
  align-self: center;
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: 0 var(--ig-space-tight);
  background: var(--ig-surface-2);
  font-size: var(--ig-font-size-small);
}



.ig-workspace {
  display: grid;
  /* THE CONTAINING BLOCK FOR §17d'S PANEL (issue 334): an absolutely positioned
     grid child with a grid area set takes that area as its containing block,
     so the panel hangs from the canvas's area without being inside its zone. */
  position: relative;
  /* HEADER SPANS, THE THREE ZONES SIT UNDER IT. The audit count is ambient: it
     belongs to the whole workspace rather than to one zone, and putting it in a
     zone's own track would make it move when that zone resized. */
  grid-template-areas:
    'header header header'
    'rail canvas inspector';
  /* THE BOARD'S ZONES AS THE FALLBACK, for a host whose browser has no
     container queries: every width the bands below cover overrides this. The
     order and the Inspector are fixed in px (ZONE_WIDTHS, issue 253), not in
     characters, so a theme's character width cannot widen them and squeeze the
     graph; the graph takes the rest. */
  grid-template-columns:
    336px
    1fr
    320px;
  grid-template-rows: auto 1fr;
  /* NO GAP, BECAUSE THE SEAMS ARE DRAWN RULES AND A RULE HAS TO REACH ITS
     CORNER. The tracks used to be separated by --ig-space, and every rule on
     this surface stopped short of the one it should have met: the header's
     border-bottom ran the full width, then a 12px band of ground, and only
     then did the rail's border-right and the inspector's border-left begin —
     three lines that never touched. The canvas toolbar's border-bottom had the
     same defect on the other axis, ending 12px shy of the rail rule at one end
     and the inspector rule at the other, so the zone it captions read as a
     floating band rather than as the top row of a column.

     THE BREATHING ROOM DID NOT GO ANYWHERE; IT MOVED INSIDE. A gap puts the
     space OUTSIDE the zone, where it separates the rule from its corner. Each
     zone's own content already carries its inset — the rail's rows and footer
     take --ig-space-wide, the canvas toolbar and the inspector take
     --ig-space — so the measured gutter between a rule and the nearest text is
     unchanged in kind, and what is gone is only the dead band the rules were
     stopping at. */
  background: var(--ig-bg);
  color: var(--ig-text-body);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  line-height: var(--ig-line-height);
}

/* THE CONTAINER IS THE MOUNT, NOT THE WORKSPACE, AND THAT IS NOT A DETAIL.
   A container query CANNOT style the element that establishes the container:
   put container-type on .ig-workspace and a rule inside @container matching
   .ig-workspace never fires. It looked right, built clean, and did nothing —
   measured at 1500px, where the rail and inspector sat at 312/312 while only
   the canvas 1fr grew. A rule that can never fire is the same class as a guard
   that can never fail, and the only reason this was caught is that the check
   compared the TRACKS either side of the breakpoint rather than asking whether
   the layout "changed".

   .ig-mount is this package's own wrapper around the workspace, so the query
   has a box to measure that is not the box it restyles. */
.ig-mount {
  container-name: ig-workspace;
  container-type: inline-size;
}

/* 17k's WIDE LAYOUT, AT THE WIDTH 17k GIVES IT FOR. A container query, not a
   viewport one, for the reason layer 1's row already answers to: the workspace
   is a box a host places, and a package that reads the window cannot be
   dropped into someone else's page.

   THE BOARD'S ZONES (Design 7b8fcbc): the order 336, the graph the rest (at
   least 480), the Inspector 320, and the band starts where the three and their
   two hairlines fit (ZONES_FIT). The order is wider than the Inspector: it
   carries a rank, a title and a meta line on one row, the Inspector a column of
   stacked blocks. Fixed in px (issue 253) so a theme's character width cannot
   widen them and squeeze the graph. */
@container ig-workspace (width >= 1138px) {
  .ig-workspace {
    grid-template-columns:
      336px
      1fr
      320px;
  }
  /* NOTHING SELECTED, NO INSPECTOR COLUMN (#330; the board's .no-insp, 336 |
     1fr): the graph takes the room an empty panel would hold. "empty", not
     "dismissed": a selection's Inspector stays at this width, dismissed or
     not, since nothing here lies over the graph to dismiss. */
  .ig-workspace[data-inspector='empty'] {
    grid-template-areas:
      'header header'
      'rail canvas';
    grid-template-columns: 336px 1fr;
  }
  .ig-workspace[data-inspector='empty'] .ig-zone[data-zone='inspector'] {
    display: none;
  }
}

.ig-zone {
  min-width: 0;
  /* Without this a long title in any zone sets that track's minimum width and
     the grid stops honouring its own template. */
  min-height: 0;
}

.ig-zone[data-zone='header'] {
  grid-area: header;
}

/* SECTION 17a's HEADER: what backlog this is, how much of it is encoded, what
   is wrong with it, how fresh the read is, and the way into a first pass. One
   row, baseline-aligned, with the first-pass entry pushed to the far end --
   the frame's only primary action on this surface.

   NOTHING HERE MOVES, for the reason the whole sheet holds: the audit count
   lives in this row, and section 17d asks for a count that never does. The
   guard on that is a literal scan over these bytes, comments included, so the
   words it looks for must not appear even in prose explaining their absence. */
.ig-workspace-header {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: var(--ig-space);
  padding: var(--ig-space-tight) var(--ig-space);
  border-bottom: var(--ig-hairline-width) solid var(--ig-hairline);
}

/* THE LOG UNDER THE HEAD: the change line, the writes still saving, and the
   writes that did not save, each with its own Retry and Discard. A full-width
   row of its own, because the header zone is the one zone drawn at every
   width.

   BOUNDED, AND SCROLLING ITSELF PAST THE BOUND. Under 640 the grid is only
   the header and the view, so a long batch of failed writes would otherwise
   push the view off a phone screen. Twelve lines of body type is about two
   recovery cards, sized in type so it follows a host that scales its type.
   The mount keeps this region's scroll offset across a redraw. */
.ig-workspace-log {
  max-height: calc(var(--ig-font-size) * var(--ig-line-height) * 12);
  overflow-y: auto;
  padding: 0 var(--ig-space) var(--ig-space-tight);
  border-bottom: var(--ig-hairline-width) solid var(--ig-hairline);
}

/* AN EMPTY LOG DRAWS NO RULE (review-219, PR 336). With no write listed and
   nothing in its live region it holds only that waiting region, and its rule
   stacked a second hairline a few pixels under the head's: the board draws one
   between the head and what follows. */
.ig-workspace-log:not(:has(.ig-recovery-list, .ig-change-line > *)) {
  padding-bottom: 0;
  border-bottom: 0;
}

/* A write named on one line (#304): the relationship it leaves, as the
   Inspector reads it, then its state. Its words are separate spans, so the
   gap is the space between them. */
.ig-log-entry,
.ig-log-write {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ig-space-snug);
  align-items: baseline;
  color: var(--ig-text);
}

/* The board mutes only the state word; the relationship reads in text. */
.ig-log-status {
  color: var(--ig-text-muted);
}

/* "not saved" and "not removed" take the failed state's colour, as the
   Inspector's failed card names its state. */
.ig-log-status[data-ig-state='failed'] {
  color: var(--ig-state-failed);
}

/* A write that did not save: its naming line above the Inspector's card. */
.ig-log-recovery {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

/* ONE CARD PER FAILED WRITE (the redesign lead's ruling). A write the
   Inspector states is drawn there, beside the issue the reader is working on,
   so the log's copy, marked data-ig-inspected, stands down wherever the
   Inspector zone is drawn: here at the widest layout, and again in the blocks
   below where the zone shows. Where it does not, under 640 and when the middle
   layout's overlay is dismissed, the log's copy comes back, so a failed write
   is never without its card. */
.ig-workspace .ig-log-recovery[data-ig-inspected] {
  display: none;
}

.ig-workspace-identity {
  color: var(--ig-text);
  font-family: var(--ig-font-mono);
}

/* The adoption pair and the freshness stamp, hoisted out of layer 1's panel
   header by #135. Quiet, because the row's only loud element is the entry at
   its far end -- these are orientation, read once and then ignored. */
.ig-workspace-counts,
.ig-workspace-freshness {
  color: var(--ig-text-muted);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
}

/* ONE SIZE ON THE LINE (#254 design read): the export draws the counts and the
   freshness as one muted span ("312 open, 64 with relationships, as of 2m
   ago" in its words), so the freshness takes the body size beside the counts. It stays out
   of the counts rule because a time takes no tabular figures. */
.ig-workspace-freshness {
  font-size: var(--ig-font-size);
}

/* BUT THE PAIR IS A COUNT, AND A COUNT IS BODY TEXT. It takes the body size
   with tabular figures, as every count both packages draw does; quiet is the
   muted colour above, not a smaller size. Its two numbers are .ig-workspace-count
   rather than layer 1's .ig-id, which names an issue rather than counting
   anything. The stamp beside it is a time, not a count, so it takes no
   tabular figures and keeps a rule of its own. */
.ig-workspace-counts,
.ig-workspace-count {
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  font-variant-numeric: tabular-nums;
}

/* THE ONLY TREATMENT STALENESS GETS, and it is why the stamp carries no word
   for it: the state is on the element, so the sheet says what a stale read
   looks like and no host has to translate an adjective. */
.ig-workspace-freshness[data-stale='true'] {
  color: var(--ig-state-invalid);
}

/* A CONTROL, NOT A CHIP. It sits inside the stamp because that is what it
   refreshes, and it takes the button reset the sheet gives every other quiet
   control on this surface rather than the accent the first-pass entry spends. */
.ig-workspace-refresh {
  margin-left: var(--ig-space-tight);
  font: inherit;
  color: var(--ig-text);
  background: var(--ig-surface-2);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: 0 var(--ig-space-tight);
  cursor: pointer;
}

.ig-workspace-refresh:hover {
  border-color: var(--ig-accent);
}

.ig-workspace-refresh:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

/* The one place the accent is spent on this surface, on the only action that
   starts something. The frame draws it as the header's primary control. */
.ig-workspace-firstpass {
  margin-left: auto;
  background: var(--ig-accent);
  color: var(--ig-bg);
  border: none;
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight) var(--ig-space);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  cursor: pointer;
}

.ig-zone[data-zone='rail'] {
  grid-area: rail;
  /* The rail scrolls; the window slides underneath. */
  overflow-y: auto;
  border-right: var(--ig-hairline-width) solid var(--ig-hairline);
  /* A COLUMN, SO THE FOOTER CAN TAKE THE SPACE A SHORT ORDER LEAVES. See
     .ig-rail-footer for why sticky alone never did. */
  display: flex;
  flex-direction: column;
}

/* NOTHING IN THE RAIL SHRINKS. A scrolling flex column will squeeze its
   children to fit before it scrolls them, and the rail's virtualization reads
   row positions off a fixed pitch — a squeezed viewer would put every offset on
   the wrong row. Every child keeps its natural height and the zone scrolls. */
.ig-zone[data-zone='rail'] > * {
  flex: none;
}

/* §17a'S RAIL FOOTER, AND IT IS THE ZONE'S LAST ROW. The frame ends the rail
   with it; that it is PINNED is this sheet's decision, on the reasoning §17c
   already settled one zone over — the rail is the scroller, mount.ts restores
   its scrollTop on every redraw, and a fact placed in the scrolled content is a
   fact you have to go back for. .ig-canvas-toolbar below pins itself against
   the other edge for exactly this reason and is the shape copied here.

   ON A SHORT RAIL IT IS PUSHED DOWN, NOT STUCK DOWN. margin-top: auto in the
   zone's column takes whatever height the order leaves, so the footer sits on
   the bottom edge whether the rail scrolls or not. An earlier note here said
   sticky alone anchored a short rail and that a column wrapper "changed
   nothing" — that was measured with the rows at 416px in a 445px track, where
   the gap left was about one footer high and flush and not-flush look alike.
   Sticky only moves a box that would otherwise leave the scrollport, so on a
   short rail it never moved at all: the footer sat directly under the last
   row with the rest of the zone empty beneath it. Sticky still does the work
   once the rail overflows; the margin does it before.

   OPAQUE, BECAUSE IT OCCLUDES. Rows slide under it, so a transparent ground
   would show the order through the count. That is also why the OPEN LIST IS NOT
   IN HERE: an element taller than its scrollport cannot stick — the browser
   clamps it and it scrolls like any other block — so a footer holding 248
   entries loses the pin exactly when it grows, and covers the whole rail on the
   way. The deeper reason is the rail's VIRTUALIZATION: railRowAt maps a scroll
   offset to a row by floor((scrollTop - chrome) / pitch), so content of
   arbitrary height anywhere in this track makes every offset below it name the
   wrong row. The list is drawn in the canvas zone, which has no such
   arithmetic. */
.ig-rail-footer {
  margin-top: auto;
  position: sticky;
  bottom: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ig-space-tight);
  padding: var(--ig-space-tight) var(--ig-space);
  border-top: var(--ig-hairline-width) solid var(--ig-hairline);
  background: var(--ig-bg);
  /* A COUNT AND ITS WORDS, SO BODY TEXT. '5 with no relationships' is read as a
     number, and the mono face it was set in is for keys; tabular figures keep
     the number from wandering as it changes. The mount measures this footer's
     height rather than deriving it, so the larger size moves nothing it
     reserves. */
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  font-variant-numeric: tabular-nums;
  line-height: var(--ig-line-height);
  color: var(--ig-text-body);
}

.ig-rail-count {
  color: var(--ig-text);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  font-variant-numeric: tabular-nums;
}

.ig-rail-isolated-toggle {
  font: inherit;
  color: var(--ig-accent);
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
}

.ig-rail-isolated-toggle:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

.ig-zone[data-zone='canvas'] {
  grid-area: canvas;
  overflow: auto;
  /* THE OVERLAY'S CONTAINING BLOCK. §17d's panel is positioned against THIS
     zone rather than the workspace, and that is what keeps it off the rail
     without a magic offset: the rail is a different grid area, so an absolutely
     positioned child of the canvas cannot reach it however wide it gets.
     RULINGS.md §3 states the constraint and gives the reason — "judging a
     finding is largely a question of what it would do to the order, so the
     order has to stay readable while you judge." */
  position: relative;
}

/* §17f'S CAPTION, AND IT IS THE ZONE'S FIRST ROW. Frame 17a puts it above the
   graph with a rule under it, which is the same shape the header row beside it
   already has — so it takes that row's padding tokens rather than a bespoke
   pair, and the two read as one band across the surface.

   THE GROUND, NOT THE CARD COLOUR. --ig-surface is what a RAISED element takes
   here: a bordered card, a button. This row is a full-bleed structural band, and
   painting it the panel colour made it read as a card floating on the canvas —
   which is also what the frame does not draw, and what the comment above it
   claimed it was not. --ig-bg is the ground .ig-workspace itself paints and the
   header row inherits, so the two really do match. It has to be OPAQUE either
   way: the row is sticky over a scrolling graph and must occlude it.

   IT DOES NOT SCROLL WITH THE CANVAS, deliberately. The zone scrolls (above),
   and a caption saying "6 of 312 shown" that scrolls away is a caption you have
   to go back for. A sticky position keeps it against the zone's top edge
   without taking the graph out of the zone's own scroll.

   THE MIDDLE ZONE'S HEAD, AS THE GRAPHS BOARD DRAWS IT: 48 tall, 16 inline
   padding, 12 between its parts, the switch at the left and the count at the
   right. 48 is 3 x --ig-space-loose; the package has no token of its own. */
.ig-canvas-toolbar {
  display: flex;
  align-items: center;
  gap: var(--ig-space);
  min-block-size: calc(var(--ig-space-loose) * 3);
  box-sizing: border-box;
  padding: 0 var(--ig-space-loose);
  border-bottom: var(--ig-hairline-width) solid var(--ig-hairline);
  position: sticky;
  top: 0;
  background: var(--ig-bg);
  z-index: 1;
}

/* THE HEAD'S COUNT, the board's .meta: body size, muted, tabular figures, one
   line. It is a read-out rather than a heading, so nothing in it is set apart
   by weight or colour. */
.ig-canvas-caption {
  margin: 0;
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  font-variant-numeric: tabular-nums;
  color: var(--ig-text-muted);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ITS OWN CLASS, NOT LAYER 1'S .ig-count. They look like the same thing and are
   not: layer 1's is the isolated-issue tally that "sits directly on the panel,
   outside the padded groups, so it carries the panel's own inset" — 12px 20px of
   it. Borrowing the name put that inset around two numbers in the middle of a
   sentence, which is what the frame comparison caught. It states the type it
   would otherwise inherit from the caption, so a rule that later moved the
   caption could not carry the count back to mono or a smaller size. */
.ig-canvas-count {
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  font-variant-numeric: tabular-nums;
}

/* THE CLAUSES DO NOT BREAK INTERNALLY. The caption is one line that ellipsizes
   as a whole; what must not happen is a label parting from the key it names, or
   a count parting from the word that says what it counts. */
.ig-canvas-focus,
.ig-canvas-shown {
  white-space: nowrap;
}

/* WHATEVER FOLLOWS THE SWITCH IS PUSHED RIGHT BY ITS OWN MARGIN, NOT BY THE
   ROW'S JUSTIFICATION. The row's arity changes: off the direct tier the caption
   is gone and the pill follows the switch alone, and justify-content would
   place the parts by count. One auto margin on the switch's next sibling is
   correct at every arity; a second auto margin on the pill would split the
   space and leave the pill midway. */
.ig-workspace .ig-canvas-switch + * {
  margin-left: auto;
}

/* THE TINT PAIR, NOT A BARE OUTLINE. The tint fill and tint border tokens
   exist for exactly this — "a fill of its own hue inside a heavier border of
   the same hue" — and the frame draws the pill that way. Reaching for the
   accent directly would give a solid chip that reads as loud as the selection.

   IT NEVER SHRINKS. The caption beside it is the part that may ellipsize; the
   pill is three or four characters and losing them would leave a coloured stub
   saying nothing. */
.ig-edit-mode {
  flex: 0 0 auto;
  font-family: var(--ig-font-mono);
  font-size: var(--ig-font-size-pill);
  letter-spacing: var(--ig-tracking-pill);
  color: var(--ig-accent);
  /* THE TINT TOKENS ARE PERCENTAGES, NOT COLOURS — 8% and 30% — so they are only
     meaningful inside color-mix, which is how every other tinted badge in the
     package consumes them. Handed straight to background and border-color they
     are invalid, and an invalid declaration is DROPPED SILENTLY: the pill
     rendered as bare cyan text with no fill and no border, and no test noticed
     because nothing here was a hex literal. */
  background: color-mix(in srgb, var(--ig-accent) var(--ig-tint-fill), transparent);
  border: var(--ig-stroke) solid
    color-mix(in srgb, var(--ig-accent) var(--ig-tint-border), transparent);
  border-radius: var(--ig-radius-small);
  padding: var(--ig-space-micro) var(--ig-space-snug);
}

/* ONE SCROLL TRACK, AND EXACTLY ONE SIBLING IS BOUNDED INSIDE IT. This zone
   holds three: §17d's AUDIT REGION, this column's selection detail, and the
   .ig-chrome the mount appends. #177 settled how they share it, and the whole
   of the answer is that the zone stays ONE track while the region alone takes a
   declared share of it (max-height: 50%, scrolling itself past that).
   .ig-inspector and .ig-chrome keep this track's own scrolling and declare no
   share, so neither can be clipped by any height.

   THE BOUNDED SIBLING IS A REGION NOW, AND THAT IS #177'S RULE KEPT RATHER THAN
   RESTATED. §17d has two surfaces — the findings panel and, since the fourth
   class moved out of it, the refused block (audit/refused.ts) — and bounding
   each at half the column lets the two of them take ALL of it, which is worse
   than the state #177 fixed rather than a smaller version of it. So
   workspace/render.ts wraps both in .ig-audit-overlay and the share is declared
   once, here, on the thing the zone actually holds. Neither leaf declares a
   size of its own; audit/styles.ts says so at both.

   AN EARLIER REVISION OF THIS COMMENT CREDITED audit/styles.ts WITH THE SHARE.
   It never carried it — that file states in as many words that the panel
   "DECLARES NO SIZE OF ITS OWN" — and the misattribution is why the fourth
   sibling nearly arrived unbounded.

   THAT IS A PROPERTY NOW, NOT A LUCKY DEFAULT, and it is what makes the chrome
   safe. A TWO-PANE VERSION WAS TRIED AND REVERTED: making the zone a flex
   column with overflow: hidden did give the audit and the selection independent
   scroll — and it CLIPPED the mount's chrome, a third sibling holding the
   target search's lower matches, the cancel button and the key legend, all of
   which lost the scrolling the zone used to give them. The lesson was read as
   "treat the chrome as a third pane"; it is better read as "do not make the
   zone a multi-pane layout at all". Bounding one sibling needs no panes.

   WHY THE PANEL IS THE ONE THAT IS BOUNDED. It is the only GLOBAL member of a
   selection-scoped zone, and renderWorkspace draws it FIRST — so unbounded, it
   is the one sibling whose length pushes a detail the reader just asked for
   below the fold. The selection detail and the chrome are both about what the
   reader is doing; the audit is about the document. §17a fixes the workspace at
   three zones plus a header, so there is nowhere else ambient for it to be, and
   a share is what makes it affordable where it has to live. */
.ig-zone[data-zone='inspector'] {
  grid-area: inspector;
  overflow-y: auto;
  border-left: var(--ig-hairline-width) solid var(--ig-hairline);
}

/* THE INSPECTOR IS A TAB STOP (#331), SO IT SHOWS WHERE THE FOCUS IS. The ring
   is drawn INSET: the zone fills its column, so a ring outside it would be
   clipped by the workspace or drawn over the canvas beside it. */
.ig-zone[data-zone='inspector']:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: calc(var(--ig-focus-ring) * -1);
}



/* THE REGION SCROLLS; ITS MEMBERS DO NOT SHRINK. Both leaves declare
   min-height: 0 — correct for each of them, because each was once the scroll
   container itself — and in a bounded flex column that is exactly the licence
   to squeeze them below their content. Measured in a browser rather than
   reasoned about: with a refusal and five findings the block was laid out 54px
   tall around 131px of content, and since a leaf's own overflow is visible it
   PAINTED OVER the panel underneath it. Nothing threw, no test failed, and the
   markup was correct — the two surfaces were simply drawn on top of each other.

   flex-shrink RATHER THAN A HEIGHT ON EITHER LEAF, which is the same layering
   the share above follows: how the region's members divide it is a fact about
   the region, and a leaf that sized itself here would be wrong in every other
   composition. The region's own max-height is what bounds the pair; this is
   what makes the overflow it declares actually reachable. */
.ig-workspace > .ig-audit-overlay > * {
  flex-shrink: 0;
}


/* §17d'S PANEL, AS AN OVERLAY OVER THE CANVAS.

   RULINGS.md §3: "a transient overlay anchored to the header count, floating
   over the canvas, 520px wide, dismissed on Escape." It was a child of the
   INSPECTOR zone until now, sharing that column's height with the selection —
   §17a fixes three zones and none of them is the audit's, so it had nowhere to
   go and took a share of the one next to it. At six findings the inspector was
   pushed below the fold.

   520px IS DESIGN'S NUMBER, not this package's, which is why it is written as
   one rather than derived from a token. It is expressed in ch units against the
   type scale so it survives a theme that changes the font size, and clamped to
   the zone so a narrow canvas cannot push it over the rail — the constraint §3
   states outright.

   ANCHORED TOP-RIGHT, under the header count it belongs to. The count sits at
   the right end of the header band, so the panel hangs from that corner and the
   eye travels the shortest distance from the control to what it opened.

   IT PAINTS OVER THE GRAPH, which is what an overlay is: z-index above the
   canvas content, and its own raised surface and shadow so the graph beneath
   reads as behind rather than as a background it is part of.

   --ig-elevation-overlay IS THE TOKEN FOR EXACTLY THIS, and the first draft
   wrote a literal rgb() instead. The package's own guard caught it, correctly:
   the theme's two shadows are deliberately the only values carrying a colour,
   so a host retheming owns them and a literal here would be invisible to that.

   PLACED IN THE CANVAS'S GRID AREA, NOT INSIDE ITS ZONE (issue 334). The panel is
   the workspace's own child so the phone layout can put it in the flow between
   the head and the Tabs; here grid-area: canvas makes that area its containing
   block, which keeps it off the rail exactly as the zone's box did. Scoped to
   the workspace's child, because the panel is a public export a consumer can
   render standalone. */
/* BORDER-BOX, AND IT IS LOAD-BEARING. There IS a universal reset in this
   codebase and it does not reach here: viewer/src/styles.ts scopes it to
   .ig-viewer descendants, and this panel is a sibling of the rail's viewer
   rather than inside it. Without it the cap is measured on the CONTENT box and
   the panel's own padding and border push the drawn box past it. Nothing looks
   broken.

   THE PANEL SCROLLS, NOT THE LIST INSIDE IT. Scrolling the list would pin the
   panel's head, which is the wrong trade twice over. The ambient count 17d
   fixes is the WORKSPACE HEADER's, drawn in the header grid area and outside
   this zone entirely - it already never moves, so a second pinned count buys
   nothing. And the list has zero horizontal padding, so making it the scroll
   container computes its overflow-x to auto and CLIPS the focus ring on every
   card's control: an outline is ink overflow, so it is cut rather than
   scrolled to. Each leaf's own padding gives those rings room. */
.ig-workspace > .ig-audit-overlay {
  grid-area: canvas;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow-y: auto;
  position: absolute;
  z-index: 3;
  top: var(--ig-space-tight);
  right: var(--ig-space-tight);
  width: min(calc(var(--ig-char-width) * 66.67), calc(100% - var(--ig-space-tight) * 2));
  max-height: calc(100% - var(--ig-space-tight) * 2);
  /* AN OVERLAY STANDS ON THE CARD'S OWN GROUND, --ig-bg (#340). It was
     --ig-surface, which is also the ground of a filled control and a selected
     tab, and a host may map that one to a translucent fill (one host's is 8%
     ink), so the panel showed the graph through it. The
     board draws an overlay opaque, on card; the elevation sets it apart. */
  background: var(--ig-bg);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  box-shadow: var(--ig-elevation-overlay);
}

/* THE AMBIENT LEFT-BAR. A 2px gold rule on the affected row and nothing else —
   no fill, no icon, no badge. §17a's whole ask is that encoding errors stay
   visible while you work rather than pulling you out of it.

   An inset box-shadow rather than a border: a border changes the row's box and
   would shift every marked row against its neighbours, which is a layout jump
   the eye reads as movement.

   IT DREW A 330px CYAN BLOCK UNTIL #122, and the comment above it — unchanged
   here because it was right — is how the defect survived. --ig-spine-width is
   §16b's SPINE CARD WIDTH (330), not a stroke; the sentence "the width is the
   theme's spine, so the bar scales with the rest of the rail" reads as a
   scaling argument and is a token mix-up. --ig-accent is the cyan the panel
   spends once on the number an operator acts on, and it is not the attention
   colour. This rule is more specific than audit/styles.ts's correct one, so
   it silently won.

   AND ITS TEST PASSED THROUGHOUT. styles.test.ts matched the rule and
   asserted it EXISTED; it never asserted what the declaration resolves to, so
   it was green about a string rather than about a property. The test below it
   now reads the values.

   ONE TREATMENT FOR ALL FOUR SEVERITIES, which is also a correction. §17d
   names exactly one ambient mark — "a 2px gold left-bar on the affected rail
   row" — and puts the severity distinction in the findings list, which
   audit/panel.ts now draws. (It read "which is host-side" until that panel
   existed; the reasoning is unaffected — the distinction still belongs to the
   list rather than to this bar — but the list is the package's now.)

   The misleading variant this replaces gave the LEAST urgent
   severity ("clearing is bookkeeping, not urgency") the alarm colour while
   every other finding got cyan, inverting the design it came from. */
.ig-zone[data-zone='rail'] [data-ig-audit] {
  box-shadow: inset var(--ig-stroke-audit) 0 0 0 var(--ig-edge-serialize-with);
}

/* THE ROWS OUTSIDE THE WINDOW, AS HEIGHT. The rail scrolls, so without a spacer
   at each end the container is exactly as tall as the drawn rows and native
   scrolling stops at the end of the first window — leaving a host no offset to
   turn into the next start, and a reader no way to reach rank 287 of 312.

   NO BACKTICKS ANYWHERE IN THIS FILE'S COMMENTS. The stylesheet is a template
   literal, so a backtick closes it — and the failure is a parse error pages
   away from the character that caused it.

   THE PITCH IS THE OUTER BOX, NOT THE ROW HEIGHT. A .ig-slot is
   min-height: --ig-row-height PLUS margin-bottom: --ig-space-tight, so
   row-to-row is the sum of the two. Sized on --ig-row-height alone, this
   undercounted EVERY omitted row by the gap — 44 of a 50px pitch on the default
   theme, so 300 omitted rows left the scroll extent 1,800px short and a host
   dividing its scroll position by the measured pitch could reach about offset
   264 of 300. The tail of the order became unreachable by the very mechanism
   added to make it reachable.

   That is a SYSTEMATIC undercount, not the approximation below, which is why it
   is corrected exactly rather than tolerated: the gap is constant per row and
   both terms are theme metrics.

   --ig-rail-rows is the count, set inline by the renderer. What remains
   approximate is only VARIABLE row height — a row carrying holds is taller than
   a bare one — so the scrollbar stays proportional rather than exact. Measuring
   that needs a mount, which this package does not have.

   THE PITCH IS THE FLOOR ALONE NOW. Layer 1's section 16 pass separates its rows
   with the panel's own hairlines instead of a margin — a row is
   --ig-row-min-height of content and a hairline, with no gap to add — so the sum
   this used to take double-counted a gap that is no longer there. The row is
   content-sized above that floor, which is the same approximation the note above
   already describes, at a slightly larger typical size. */
.ig-rail-spacer {
  /* The rail's pitch: a dense row and the hairline under it, the same two
     tokens the mount's railRowAt divides by (review-41 on PR 341). */
  height: calc((var(--ig-row-height-dense) + var(--ig-hairline-width)) * var(--ig-rail-rows, 0));
}

.ig-inspector {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space);
  padding: var(--ig-space);
}

/* TWO EMPTIES, ONE TREATMENT. "Nothing is selected" and "this issue is related
   to nothing" are different facts and the panel states each in its own place —
   but they are the same KIND of statement, a quiet line where content would be,
   and giving them separate looks would suggest a distinction that is not
   there. */
.ig-inspector-empty,
.ig-inspector-none {
  margin: 0;
  color: var(--ig-text-muted);
  font-size: var(--ig-font-size-small);
}

/* The panel's heading row: the name at one end, the way out at the other.
   Baseline-aligned rather than centred, so a heading in caps and a button in
   sentence case sit on one line rather than on two optical ones. */
.ig-inspector-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ig-space-tight);
}

.ig-inspector-issue,
.ig-inspector-issues {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

/* A SELECTED SET, LISTED AS TEXT: one issue a line, title then key, the key in
   the muted role the rail's own id chips use. Nothing here is a control. */
.ig-inspector-set {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

.ig-inspector-set-item {
  color: var(--ig-text-body);
}

.ig-inspector-set-item .ig-id {
  color: var(--ig-text-muted);
}

/* THE BATCH INSPECTOR (#249, the design's "Several issues at once"): "Add to
   all 3" over three secondary offers, the reason a refused offer is disabled
   under them in muted text, the one-issue search for "All 3 are blocked by…",
   and the confirm that states the number of writes, its write the one primary
   control in the panel. */
.ig-batch,
.ig-batch-pick {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

/* The containing block for the Command popover under the offers. */
.ig-batch {
  position: relative;
}

.ig-batch-offers,
.ig-batch-card-foot,
.ig-batch-note-acts {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ig-space-tight);
}

.ig-batch-offer:disabled {
  color: var(--ig-text-muted);
  cursor: not-allowed;
}

/* The one paragraph in the block is the reason a refused offer is disabled. */
.ig-batch > p,
.ig-batch-pick-head {
  margin: 0;
  color: var(--ig-text-muted);
  font-size: var(--ig-font-size-small);
}

.ig-batch-query {
  background: var(--ig-bg);
  color: var(--ig-text-body);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight) var(--ig-space);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
}

/* "All 3 are blocked by…": THE COMMAND POPOVER the board draws, a card over
   the panel under the offers, never a block that pushes the panel down. */
.ig-batch-pick {
  position: absolute;
  inset-inline: 0;
  top: 100%;
  z-index: 2;
  padding: var(--ig-space-tight);
  background: var(--ig-surface);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius-large);
  box-shadow: var(--ig-elevation-overlay);
}

.ig-batch-pick-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.ig-batch-pick-item {
  display: flex;
  gap: var(--ig-space-tight);
  width: 100%;
  background: none;
  color: var(--ig-text-body);
  border: none;
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  text-align: start;
  cursor: pointer;
}

.ig-batch-pick-item:hover,
.ig-batch-pick-item[aria-selected='true'] {
  background: var(--ig-surface-2);
}

/* THE BATCH CONFIRM IS DRAWN OVER THE PAGE, as RULES draws every confirm: a
   scrim over the whole workspace, so nothing behind it takes a press until it
   is answered, and the card centred on it. The scrim is the ground colour,
   part-transparent, so it stays the theme's. (The audit's surfaces stay
   ambient: this is the one confirm, and it asks before writes.) */
.ig-batch-scrim {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: grid;
  place-items: center;
  padding: var(--ig-space);
  background: color-mix(in srgb, var(--ig-bg) 60%, transparent);
}

.ig-batch-card {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
  inline-size: min(100%, calc(var(--ig-char-width) * 56));
  padding: var(--ig-space);
  background: var(--ig-surface);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius-large);
  box-shadow: var(--ig-elevation-overlay);
}

.ig-batch-card-title {
  margin: 0;
  font-size: inherit;
  font-weight: var(--ig-weight-medium);
}

.ig-batch-card-body {
  margin: 0;
  color: var(--ig-text-body);
  font-size: var(--ig-font-size-small);
}

.ig-batch-card-foot {
  justify-content: flex-end;
}

.ig-batch-confirm {
  background: var(--ig-accent);
  color: var(--ig-bg);
  border: none;
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight) var(--ig-space);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  cursor: pointer;
}

/* A PARTIAL BATCH'S NOTE, in the log under the head: how many saved, and the
   two ways to finish it. A write nobody discarded stays owed. */
.ig-batch-note {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ig-space-tight);
  padding: var(--ig-space-tight) 0;
}

.ig-batch-note-title {
  color: var(--ig-text-body);
  font-size: var(--ig-font-size-small);
}

.ig-inspector-title {
  margin: 0;
  font-size: var(--ig-font-size);
  color: var(--ig-text);
}

.ig-inspector-holds {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

/* The two hold families never share a treatment — layer 1's rule, carried
   across so the inspector cannot contradict the rail it sits beside. */
.ig-inspector-hold[data-family='graph'] {
  color: var(--ig-station-held);
}

.ig-inspector-hold[data-family='tracker'] {
  color: var(--ig-text-muted);
}

/* The holder, as a control: inline with the sentence that names it, drawn as
   the same kind of button the relationship rows use so a reader learns one
   affordance for "take me to that issue". */
.ig-inspector-hold-subject {
  margin-left: var(--ig-space-tight);
  background: var(--ig-surface-2);
  color: inherit;
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: 0 var(--ig-space-tight);
  font-family: var(--ig-font-mono);
  font-size: var(--ig-font-size-small);
  cursor: pointer;
}

.ig-inspector-hold-subject:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

.ig-inspector-relationships {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

/* §17a PUTS '+ add' ON THE HEADING'S ROW, opposite the heading. The list
   between them is unbounded, so a control after it drifts down the panel as a
   subject gains relationships; here its position does not depend on content. */
.ig-inspector-relationships-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ig-space-tight);
}

/* SECTION 17a DRAWS EVERY INSPECTOR HEADING IN CAPS -- WHY RANK 2,
   RELATIONSHIPS, ADD RELATIONSHIP -- so the treatment is shared rather than
   spelled per heading. Tracking widens with the caps because letterforms at a
   small size need it; that is what --ig-tracking-label is for. */
.ig-inspector-heading,
.ig-inspector-name,
.ig-why-rank-heading {
  margin: 0;
  font-size: var(--ig-font-size-small);
  color: var(--ig-text-muted);
  text-transform: uppercase;
  letter-spacing: var(--ig-tracking-label);
}

/* THE EXPLANATION, SECTION 17a's WHOLE POINT FOR THIS ZONE. The clauses are
   inline spans so the block reads as one sentence rather than a list of
   findings: the reader asked one question. */
.ig-why-rank {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

.ig-why-rank-sentence {
  margin: 0;
  color: var(--ig-text-body);
}



/* THE PANEL'S TWO QUIET BUTTONS SHARE ONE TREATMENT — clear and cancel. They
   are the same affordance at two moments (leave this selection, abandon the
   draft) and drawing them two ways would invent a hierarchy the design does
   not state.

   '+ add' WAS THE THIRD AND HAS LEFT THE SET, because frame 17a moved it and
   redrew it: on the relationships header row it is unbordered accent text with
   the key beside it, not a filled box. That is a hierarchy the design DOES
   state — a header affordance reads differently from a control in the panel
   body — so matching it here is following the frame rather than inventing a
   difference. Its focus ring is still shared, below. The destructive controls are
   deliberately NOT in this set: a row's '✕' is a glyph in the row's own slot,
   and the mount's delete button carries its own danger treatment.

   ALIGNMENT IS NOT PART OF THE TREATMENT, and putting it here was a silent
   contradiction. 'align-self: flex-start' belongs to the two buttons in
   '.ig-inspector-add', a COLUMN, where without it they stretch to the panel's
   full width. The clear button sits in '.ig-inspector-head', a baseline row —
   and 'align-self' beats the container's 'align-items', so it overrode the
   baseline that rule's own comment says it is there to get. Declared where each
   is true instead. */
.ig-inspector-clear,
.ig-inspector-cancel,
.ig-batch-offer,
.ig-batch-cancel,
.ig-batch-retry,
.ig-batch-discard {
  background: var(--ig-surface-2);
  color: var(--ig-text-body);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight) var(--ig-space);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  cursor: pointer;
}

.ig-inspector-clear:focus-visible,
.ig-inspector-addbutton:focus-visible,
.ig-inspector-cancel:focus-visible,
.ig-relationship-more:focus-visible,
.ig-batch-offer:focus-visible,
.ig-batch-cancel:focus-visible,
.ig-batch-confirm:focus-visible,
.ig-batch-retry:focus-visible,
.ig-batch-discard:focus-visible,
.ig-batch-pick-item:focus-visible,
.ig-batch-query:focus-visible {
  /* '+ add' keeps the shared focus ring though it left the shared fill: a
     focus indicator is an accessibility guarantee, not a visual register. */
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

/* §17a's '+ add', AS THE FRAME DRAWS IT: accent text on the header row, no box.
   It is a header affordance rather than a control in the panel body, and the
   frame states that difference by removing the border and the fill rather than
   by moving it alone. */
.ig-inspector-addbutton {
  display: inline-flex;
  align-items: baseline;
  gap: var(--ig-space-micro);
  background: none;
  border: none;
  border-radius: var(--ig-radius);
  padding: 0;
  color: var(--ig-accent);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  cursor: pointer;
}

/* THE KEY, QUIETER THAN THE ACT IT NAMES. It is a hint about how to reach the
   control, not part of the control's label, so it takes the muted tone the
   panel gives every line that states a fact rather than offering an act.
   UPPERCASED HERE, NEVER IN THE MARKUP: the binding table stores the lowercase
   key a press normalizes to, and drawing 'R' is presentation. A second,
   uppercase copy in the package would be the drift RELATE_KEY exists to end. */
.ig-inspector-addkey {
  color: var(--ig-text-muted);
  font-family: var(--ig-font-mono);
  text-transform: uppercase;
}

.ig-relationship-list {
  list-style: none;
  /* The board's '.ig-rels': rows touch, and the list pulls out by a row's
     inset so each glyph sits flush with the heading above (#308). */
  margin: calc(var(--ig-space-micro) * -2) calc(var(--ig-space-snug) * -1) 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* ONE KIND'S GROUP (RULES, Graphs, Dense neighbourhoods): its words and count
   in small muted type on one row, its first five rows, then "Show 4 more"
   under them, set flush to the rows' start. */
.ig-relationship-group {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-micro);
}

.ig-relationship-group-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ig-space-tight);
  color: var(--ig-text-muted);
  font-size: var(--ig-font-size-small);
  font-weight: var(--ig-weight-medium);
}

.ig-relationship-count {
  font-variant-numeric: tabular-nums;
}

/* A GHOST BUTTON: words only, no fill or border at rest, so it reads as the
   list's own continuation rather than an action beside it. */
.ig-relationship-more {
  align-self: flex-start;
  margin-block-start: var(--ig-space-micro);
  border: 0;
  border-radius: var(--ig-radius);
  background: none;
  color: var(--ig-text-body);
  font-family: inherit;
  font-size: inherit;
  font-weight: var(--ig-weight-strong);
  padding: var(--ig-space-tight);
  cursor: pointer;
}

.ig-relationship-more:hover {
  background: var(--ig-surface-2);
}

/* IT WRAPS RATHER THAN TRUNCATES, which is '.ig-picker-direction''s rule
   inherited along with §17b's statement. A qualified reference is long —
   'owner/repo#602' — the inspector is a fixed 320-wide track with no
   horizontal scroll, and a row that cannot wrap pushes its trailing controls
   out of the zone entirely. A statement whose object is cut off says something
   other than what the format holds, and a flip a reader cannot reach is the
   affordance this row exists to offer.

   ON THE ROW AND ON THE STATEMENT BOTH. The row wraps so the slot and the flip
   drop to a second line rather than overflow; '.ig-relationship-select' below
   wraps so the reference pair does the same inside it. Wrapping one without the
   other leaves the other overflowing. */
/* "SHOW #2239" IS A BUTTON STYLED AS A LINK (Design's 'button.link', #308): no
   box, no padding, the accent ink, underlined, at the row's own size. */
.ig-log-show {
  background: none;
  border: 0;
  padding: 0;
  font: inherit;
  color: var(--ig-link);
  text-decoration: none;
  cursor: pointer;
}

/* The board's '.link': no underline at rest; hovered, a 1 underline 3 below. */
.ig-log-show:hover {
  color: var(--ig-link-hover);
  text-decoration: underline;
  text-decoration-thickness: var(--ig-hairline-width);
  text-underline-offset: calc(var(--ig-space-micro) * 1.5);
}

.ig-log-show:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-micro);
}

/* THE BOARD'S UNBOXED TWO-LINE ROW (RULES, Relationships; '.ig-rel', #308):
   the phrase and number, then the other issue's title in text-muted, with the
   row's controls on the right across both lines. No box: hover takes the
   secondary fill and the selected row the strong fill. */
.ig-relationship {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  column-gap: var(--ig-space-snug);
  align-items: center;
  padding: var(--ig-space-snug);
  border-radius: var(--ig-radius);
}

.ig-relationship:hover {
  background: var(--ig-surface-2);
}

.ig-relationship[data-ig-selected='true'] {
  background: var(--ig-fill-strong);
}

.ig-relationship > .ig-relationship-select,
.ig-relationship > .ig-relationship-name {
  grid-column: 1;
  grid-row: 1;
}

/* The second line starts under the phrase, past the glyph's column. */
.ig-relationship-other {
  grid-column: 1;
  grid-row: 2;
  display: flex;
  min-inline-size: 0;
  white-space: nowrap;
  padding-inline-start: calc(var(--ig-space-loose) + var(--ig-space-snug));
  color: var(--ig-text-muted);
}

/* THE TITLE GIVES WAY, THE NOTE DOES NOT: " · set on the other issue" says why
   the row has no remove, so a long title cannot hide it (review-41, PR 325). */
.ig-relationship-title {
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ig-relationship-note {
  flex: none;
}

.ig-relationship > .ig-relationship-remove,
.ig-relationship > .ig-relationship-state {
  grid-column: 2;
  grid-row: 1 / 3;
}

.ig-relationship > .ig-relationship-flip {
  grid-column: 3;
  grid-row: 1 / 3;
}

/* HUE BY FIELD, ONCE, FOR EVERY ELEMENT THAT CARRIES 'data-edge'. From the
   theme's own edge tokens — the same channel layer 1 uses — so a relationship
   reads the same colour in the row and in the kind-list entry it was chosen
   from as it does on the canvas. The refusal capsule is deliberately NOT in
   this set: its whole border is the invalid state's dotted stroke, and a hue on
   its left edge would overwrite the half of that a reader looks for first.

   WRITTEN PER FIELD RATHER THAN FROM A 'data-edge'-KEYED TOKEN, because CSS has
   no way to build 'var(--ig-edge-' + attr() + ')': 'attr()' is usable in
   'content' and nowhere a custom property name is read. Five rules is the cost
   of that, and the alternative the package rejected is a token per hue set
   inline by the renderer, which moves a theme value into markup.

   ONE SELECTOR LIST PER FIELD, AND THAT IS THE POINT OF THIS BLOCK. The kind
   list arrived with a verbatim second copy of these five rules under
   '.ig-kind-option' — same five fields, same five tokens — under a comment
   claiming the file should not hold two ways of reading the theme while it
   held the same way twice. A sixth field is now one line here, not two. */
.ig-relationship[data-edge='blocked-by'],
.ig-kind-option[data-edge='blocked-by'] {
  border-left-color: var(--ig-edge-blocked-by);
}

.ig-relationship[data-edge='duplicate-of'],
.ig-kind-option[data-edge='duplicate-of'] {
  border-left-color: var(--ig-edge-duplicate-of);
}

.ig-relationship[data-edge='serialize-with'],
.ig-kind-option[data-edge='serialize-with'] {
  border-left-color: var(--ig-edge-serialize-with);
}

.ig-relationship[data-edge='together-with'],
.ig-kind-option[data-edge='together-with'] {
  border-left-color: var(--ig-edge-together-with);
}

.ig-relationship[data-edge='decomposed-from'],
.ig-kind-option[data-edge='decomposed-from'] {
  border-left-color: var(--ig-edge-decomposed-from);
}

/* THE DESCRIPTION'S BOX, WHETHER OR NOT A CONTROL IS WRAPPING IT. A row's head
   is a button and a phantom capsule's is a plain span -- 'render.ts' withholds
   the selector for an edge the landed document does not carry -- and the two
   occupy the row identically: they fill it, so the reason wraps under them
   rather than squeezing the reference out, and their parts sit on one baseline.
   Declared once, so the capsule cannot come to sit differently from the row it
   stands in for. */
.ig-relationship-select,
.ig-relationship-name {
  display: block;
  min-inline-size: 0;
  overflow-wrap: anywhere;
}

/* The button fills its row, so the whole relationship is the hit target rather
   than the words inside it. Transparent and borderless: the li already carries
   the border and the hue, and a second box around it would read as two
   controls. */
.ig-relationship-select {
  background: none;
  border: none;
  padding: 0;
  font-family: inherit;
  font-size: inherit;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.ig-relationship-select:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

/* The glyph and its word are one phrase, so they get their own gap rather than
   inheriting the row's — which spaces the phrase from the reference beside it,
   a wider relationship. NOT a literal space character in the markup: the word
   is the vocabulary's and this package does not add characters to it, which is
   the same rule the why-rank sentence's clauses are spaced by. */
.ig-relationship-kind {
  color: var(--ig-text);
}

/* THE GLYPH'S COLUMN, 16 wide in text-muted and 8 from the words, as the
   board's icon column; the phrase and its number are one text space apart. */
.ig-relationship-kind > .ig-glyph {
  display: inline-block;
  inline-size: var(--ig-space-loose);
  margin-inline-end: var(--ig-space-snug);
  text-align: center;
  color: var(--ig-text-muted);
}

/* The number reads with its phrase, in the phrase's ink and tabular digits. */
.ig-relationship-ref {
  color: var(--ig-text);
  font-variant-numeric: tabular-nums;
}

/* THE RIGHT-HAND SLOT: the remove, or on the selected row the spoken state.
   An inbound row has neither; its second line says it is set on the other
   issue (#308). '.ig-relationship-flip' below sits beside the slot. */
.ig-relationship-state {
  align-self: center;
  color: var(--ig-text-muted);
  font-size: var(--ig-font-size-small);
  text-transform: uppercase;
  letter-spacing: var(--ig-tracking-label);
}

/* The selected row names the state the canvas is drawing a halo for, so it
   takes the focus hue rather than the muted one — one selection, one colour,
   across the zones. */
.ig-relationship-state[data-ig-state='selected'] {
  color: var(--ig-focus);
}

/* A GLYPH BUTTON, SIZED BY ITS GLYPH. No border and no fill: the row already
   carries a border, and a second box inside it would read as two controls —
   the same reasoning '.ig-relationship-select' records. */
.ig-relationship-remove {
  align-self: center;
  background: none;
  border: none;
  padding: 0 var(--ig-space-tight);
  color: var(--ig-text-muted);
  font-family: inherit;
  font-size: inherit;
  line-height: 1;
  cursor: pointer;
}

.ig-relationship-remove:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

/* §17b's FLIP, AT THE ROW'S END. It is drawn last and needs no margin of its
   own to get there: '.ig-relationship-select' above carries 'flex: 1', so the
   statement takes the free space and everything after it is already pushed to
   the end — which is where frame 17b draws this control. A 'margin-left: auto'
   here would be inert, and a comment crediting it would be an explanation that
   outlived the thing it explained.

   A BORDERED CONTROL RATHER THAN THE REMOVE'S BARE GLYPH, which is the frame's
   own distinction and not decoration: '✕' is a mark a reader recognises without
   a box, and 'flip' is a word that would otherwise read as part of the sentence
   it sits beside. The border is what says it is pressable.

   ITS FOCUS RING IS NOT OPTIONAL, and it takes the offset the row's OTHER two
   controls already use rather than the one it was born with. This rule came
   from the picker's sheet, where the ring sat a hairline out;
   '.ig-relationship-select' and '.ig-relationship-remove' share this row and
   both ring at '--ig-space-tight', and one control ringing tighter than its
   neighbours reads as a rendering fault rather than as a distinction. This is
   the control §17b calls the guard against the most common encoding mistake; a
   keyboard reader who cannot see where they are has it and not its affordance. */
.ig-relationship-flip {
  align-self: center;
  background: var(--ig-surface);
  color: var(--ig-text-body);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: 0 var(--ig-space-tight);
  font-family: inherit;
  font-size: var(--ig-font-size-small);
  line-height: inherit;
  cursor: pointer;
}

.ig-relationship-flip:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

/* A REFUSED EDIT, IN THE ROW IT WOULD HAVE BEEN. It borrows the ghost the
   canvas draws for the same state — a dotted edge in the invalid hue — so the
   line and the row a reader looks between are recognisably one fact.
   NO OPACITY HERE. 'overlay/grammar.ts' holds the opacity every write state is
   drawn at, on the record that a second copy would drift; what this sheet
   contributes is the structure. */
.ig-relationship-refused {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ig-space-tight);
  align-items: baseline;
  padding: var(--ig-space-tight);
  border: var(--ig-stroke) dotted var(--ig-state-invalid);
  border-radius: var(--ig-radius);
  background: var(--ig-surface);
}

.ig-relationship-reason {
  color: var(--ig-state-invalid);
  font-size: var(--ig-font-size-small);
}

/* THE REFUSAL'S ONE CONTROL, SECONDARY AND SMALL (issue 285, the redesign
   lead's call): the flip's quiet bordered button at the small size, so it
   reads as an action on the refused write and never outranks the reason it
   follows. Its ring matches every other control in the row. */
.ig-refusal-discard {
  background: var(--ig-surface);
  color: var(--ig-text-body);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: 0 var(--ig-space-tight);
  font-family: inherit;
  font-size: var(--ig-font-size-small);
  line-height: inherit;
  cursor: pointer;
}

.ig-refusal-discard:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

/* A REFUSAL ON A RELATIONSHIP THAT IS STILL THERE. The row stays — it names a
   real edge and its remove control still works — so this marks it rather than
   replacing it: the capsule's dotted stroke, and room for the reason to wrap
   under the row rather than squeezing the reference out of it.
   BORDER-STYLE ONLY, NOT BORDER-COLOR: the field's hue is on the left edge from
   the block above, and a shorthand here would overwrite it and take the row's
   one colour channel away on exactly the rows carrying the most information. */
.ig-relationship[data-ig-code] {
  border: var(--ig-stroke) dotted var(--ig-line);
}

/* THE REASON AND ITS DISCARD GO UNDER THE ROW'S TWO LINES, starting under the
   phrase as the second line does. Left to auto-placement they took the
   control columns beside the name and squeezed the reference to a word a line
   (issue 285's capture). The remove and the flip keep their two rows. */
.ig-relationship > .ig-relationship-reason {
  grid-column: 1;
  grid-row: 3;
  padding-inline-start: calc(var(--ig-space-loose) + var(--ig-space-snug));
}

.ig-relationship > .ig-refusal-discard {
  grid-column: 1;
  grid-row: 4;
  justify-self: start;
  margin-inline-start: calc(var(--ig-space-loose) + var(--ig-space-snug));
  margin-block-start: var(--ig-space-tight);
}

/* THE KIND STEP'S OWN BOX — the heading, the numbered list and the cancel that
   withdraws from it.

   IT NO LONGER HOLDS '+ add'. This box was once "one place the reader returns
   to", holding whichever of the two create steps was live; frame 17a splits
   them by zone, putting '+ add' on the relationships header row and leaving the
   kinds here under a heading of their own. The two steps are still exclusive —
   'createStep' answers one of them — but they are no longer drawn in one
   place, so this rule is about the kind step alone. */
.ig-inspector-add {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

/* Sized by its own word rather than stretched across the column — see the
   quiet-button rule above, which deliberately does not carry this.

   '+ add' IS NO LONGER LISTED HERE, and dropping it was required rather than
   tidy. This declaration is scoped to '.ig-inspector-add', a COLUMN; '+ add'
   now sits in the relationships header, a ROW, where 'align-self' beats the
   container's 'align-items' and would top-align the control against the
   heading — the exact bug the '.ig-inspector-clear' comment above records
   having already been fixed once. */
.ig-inspector-cancel {
  align-self: flex-start;
}

/* WHOSE DRAFT THIS IS, drawn only when it is not the panel's subject. Quiet and
   small, like every other line that states a fact rather than offering an act:
   it is a caption on the step below it, not a heading over it. The reference
   inside keeps layer 1's '.ig-id' treatment, so the issue reads the same here
   as it does in the why-rank sentence. */
.ig-inspector-source {
  margin: 0;
  color: var(--ig-text-muted);
  font-size: var(--ig-font-size-small);
}

.ig-kind-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-micro);
}

/* Full width, so the whole entry is the hit target.

   THE DIGIT IS A CHIP AT THE ROW'S END, which is frame 17a's device and
   REVERSES the placement #144 shipped. That decision was made in the same §17a
   pass and with this frame available, so it is overturned on the merits rather
   than as an oversight: what made the old left-hand column read as a set of
   KEYS was vertical alignment, which a label long enough to wrap breaks, while
   a bordered chip carries the key-cap signal on each row by itself and cannot
   come apart. Reversing a same-campaign decision is called out on the pull
   request so autnmy/issuegraph#147 rules rather than the implementer.

   CENTRED, NOT BASELINE-ALIGNED. A chip has its own border and padding, so on a
   baseline it sits low against the glyph and the label; the frame's row centres
   all three. */
.ig-kind-option {
  width: 100%;
  display: flex;
  gap: var(--ig-space-tight);
  align-items: center;
  background: var(--ig-surface);
  color: var(--ig-text-body);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight);
  font-family: inherit;
  font-size: var(--ig-font-size-small);
  text-align: left;
  cursor: pointer;
}

.ig-kind-option:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

/* THE CHIP TAKES THE SLACK BEFORE IT, rather than the label being told to grow.
   The label is drawn by layer 1's shared 'glyphAndLabel' and carries no class of
   its own, so selecting it from here means selecting by exclusion — a rule that
   silently stops matching the day that helper adds an element. An auto margin
   is stated on the element this rule already owns, needs nothing of the label,
   and puts the chip at the row's end whatever precedes it. */
.ig-kind-digit {
  flex: 0 0 auto;
  margin-left: auto;
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: 0 var(--ig-space-micro);
  font-family: var(--ig-font-mono);
  color: var(--ig-text-muted);
}

/* §17b's RECOVERY CARDS. An unsettled write the reader can still act on, drawn
   where they made it.
   THE HUE COMES FROM THE STATE, through the same custom properties the canvas
   draws the line with — so a card and the edge it is about are recognisably one
   fact, and a host retheming the palette moves both at once. The tokens are
   named per state below rather than set once, because '--ig-state-failed' and
   '--ig-state-conflict' are different channels and a shared variable here would
   be a third place the pairing could drift.
   NO OPACITY, for the reason the refusal capsule states: 'overlay/grammar.ts'
   holds what each write state is drawn at, and this sheet contributes structure. */
.ig-recovery-region {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
  margin-top: var(--ig-space);
}

.ig-recovery-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

.ig-recovery {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
  padding: var(--ig-space-tight);
  border-radius: var(--ig-radius);
  background: var(--ig-surface);
  border: var(--ig-stroke) solid var(--ig-line);
}

/* GHOST + THE ✕ THE CANVAS DRAWS. §17b gives a failed write a ghosted line with
   a cross terminal; the card carries the same hue so the two read together. */
.ig-recovery[data-ig-state='failed'] {
  border-color: var(--ig-state-failed);
  border-style: dashed;
}

/* THE GOLD DOUBLE RULE. §17b draws a conflict as a doubled line holding two
   versions. 'border-style: double' is the card's half of that grammar — the
   LINE's half is the 'second-version' mark, which needs a position this layer
   does not have and is issue #102's. */
.ig-recovery[data-ig-state='conflict'] {
  border-color: var(--ig-state-conflict);
  border-style: double;
  border-width: calc(var(--ig-stroke) * 3);
}

.ig-recovery-name {
  margin: 0;
  font-size: var(--ig-font-size-small);
  font-weight: 600;
}

.ig-recovery[data-ig-state='failed'] .ig-recovery-name {
  color: var(--ig-state-failed);
}

.ig-recovery[data-ig-state='conflict'] .ig-recovery-name {
  color: var(--ig-state-conflict);
}

.ig-recovery-reason,
.ig-recovery-refresh-error {
  margin: 0;
  font-size: var(--ig-font-size-small);
  color: var(--ig-text-muted);
}

.ig-recovery-refresh-detail {
  font-family: var(--ig-font-mono);
}

/* THE THREE RESOLUTIONS, IN A ROW AND NEVER IN A MENU. §17b lists them as
   peers; nesting one behind a disclosure would rank them, and the one that
   would end up hidden is 'view diff' — the one that lets a reader decide
   between the other two. */
.ig-recovery-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ig-space-tight);
}

.ig-recovery-action {
  background: var(--ig-surface);
  color: var(--ig-text-body);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight);
  font-family: inherit;
  font-size: var(--ig-font-size-small);
  cursor: pointer;
}

.ig-recovery-action:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

.ig-recovery-action[aria-pressed='true'] {
  border-color: var(--ig-focus);
}

/* TWO SIDES, SIDE BY SIDE, AND NOTHING BETWEEN THEM THAT COMBINES THEM. The
   layout is the design constraint: there is no column for a merged result,
   because there is no merged result to put in one. */
.ig-recovery-diff {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
  padding-top: var(--ig-space-tight);
  border-top: var(--ig-hairline-width) solid var(--ig-hairline);
}

/* ONE SIDE OF THE DIFFERENCE. Stacked rather than columned: at a panel's width
   two columns give each side about half of an already narrow zone, and a
   relationship row is a sentence rather than a cell. */
.ig-recovery-side {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

.ig-recovery-side-name {
  margin: 0;
  font-size: var(--ig-font-size-small);
  color: var(--ig-text-muted);
  font-weight: 400;
}

.ig-recovery-edges,
.ig-recovery-issues {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

.ig-recovery-edge,
.ig-recovery-issue {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ig-space-tight);
  align-items: baseline;
  font-size: var(--ig-font-size-small);
}

/* BOTH TITLES, NEITHER STRUCK THROUGH. A strike-out would say the old one is
   gone, which is exactly the judgement this card must not make for the reader. */
.ig-recovery-was,
.ig-recovery-now {
  color: var(--ig-text-muted);
}

.ig-recovery-now {
  color: var(--ig-state-conflict);
}

.ig-recovery-diff-empty {
  margin: 0;
  padding-top: var(--ig-space-tight);
  border-top: var(--ig-hairline-width) solid var(--ig-hairline);
  font-size: var(--ig-font-size-small);
  color: var(--ig-text-muted);
}

/* §17c ON THE ROW: the tint, the third column, and the chip in place.

   THE TINT IS DRAWN FROM AN ATTRIBUTE rather than from a class the row is
   given, which is audit/surface.ts's precedent and its reason: layer 1 owns
   the row's markup, so layer 2 says WHICH KIND and the stylesheet says what
   that kind looks like. A row the edit did not touch carries no attribute at
   all, so none of these rules can reach it, and "unaffected rows are left
   completely alone" is structural rather than asserted.

   THESE REACH LAYER 1'S OWN CLASSES, and that is a deliberate exception of
   exactly the shape reevaluate/styles.ts already declares for the greyed rail:
   only from INSIDE this surface's own root, and only for a state layer 1 does
   not model. The viewer draws a row; whether the last edit moved that row is a
   fact only the store knows, so the mark belongs to whoever knows it.

   BOTH ROW SHAPES, because a delta can land on either. A ranked row is an
   .ig-slot; an excluded one — the shape an issue takes when an edit turns it
   into a duplicate — is an .ig-footer-row, and it is still navigable, so
   reevaluateView still places its chip. An earlier revision listed .ig-slot
   only, so a left row got its chip and its extended name and no ground.

   EVERY VALUE deltaKind CAN EMIT, and that list is readiness, then a
   movement's direction, then a presence: promoted, newly-held, up, down,
   entered, left. An earlier revision keyed a rule on 'absent', which is not a
   value this code has ever produced — presence is 'entered' | 'left' — so that
   rule matched nothing while looking like the neutral case, and a left row
   took the READY tint from the bare fallback below. Named exhaustively now
   rather than defaulted, so a seventh value renders untinted rather than
   wrong.

   BACKGROUND-COLOR, NEVER THE SHORTHAND. the background shorthand resets background-image
   to none, and layer 1 draws the HELD row's hatch as a repeating-linear-
   gradient on exactly that property. These rules are more specific and load
   after it, so the shorthand silently took the hatch off any row that was both
   held and changed — which is not a corner: newly-held is the delta that
   co-occurs with data-held='true' by definition, so the most common overlap
   lost the held channel entirely. The longhand leaves the gradient alone.

   COLOUR-MIX ON THE TOKEN THE KIND ALREADY NAMES, at the strength layer 1
   tints its own rows with. Inventing --ig-row-promoted would put a hue in this
   package that a host retheming the station colours could not move in step,
   and inventing a percentage would make this tint drift from the unit tint
   layer 1 draws with --ig-tint-unit. */
.ig-workspace .ig-slot[data-ig-delta='promoted'],
.ig-workspace .ig-slot[data-ig-delta='up'],
.ig-workspace .ig-slot[data-ig-delta='entered'],
.ig-workspace .ig-footer-row[data-ig-delta='promoted'],
.ig-workspace .ig-footer-row[data-ig-delta='up'],
.ig-workspace .ig-footer-row[data-ig-delta='entered'] {
  background-color: color-mix(in srgb, var(--ig-station-ready) var(--ig-tint-unit), transparent);
}

.ig-workspace .ig-slot[data-ig-delta='newly-held'],
.ig-workspace .ig-slot[data-ig-delta='down'],
.ig-workspace .ig-footer-row[data-ig-delta='newly-held'],
.ig-workspace .ig-footer-row[data-ig-delta='down'] {
  background-color: color-mix(in srgb, var(--ig-station-held) var(--ig-tint-unit), transparent);
}

/* A row the edit took OUT of the order. Neutral rather than held: it is not
   waiting on anything, it is simply no longer ranked. */
.ig-workspace .ig-slot[data-ig-delta='left'],
.ig-workspace .ig-footer-row[data-ig-delta='left'] {
  background-color: color-mix(in srgb, var(--ig-text-muted) var(--ig-tint-unit), transparent);
}

/* A RECEDED ROW DRAWS LAYER 1'S RECEDED GROUND, TINTED OR NOT.

   The tints above tie layer 1's recede ground on specificity and this sheet
   loads after it, so without this rule a receded row that the edit also
   changed kept its tint and read as one the selection touches. Placed after
   every tint so it wins by order at the same specificity. The delta chip and
   the row's accessible name still report the change. Background-color, never
   the shorthand, for the held hatch's sake, as above. The footer selector
   names .ig-linear, as layer 1's does: the canvas graph draws footer rows
   too, and a receded graph row takes no ground. */
.ig-workspace .ig-slot[data-recede='true'],
.ig-workspace .ig-linear .ig-footer-row[data-recede='true'] {
  background-color: var(--ig-surface-2);
}

/* THE THIRD COLUMN IS WHAT PUTS THE CHIP AT THE ROW'S TRAILING EDGE.

   The frame draws the row as rank, body, chip — three columns, the last
   sized to its content. Layer 1's own rule is a TWO-column grid, so a chip
   appended as a third child wrapped onto an implicit second row and sat under
   the rank. That was visible in the first capture of this pair, and it is why
   this rule is a column template rather than a margin: in a grid, an auto
   inline margin cannot move an item that is in the wrong row to begin with.

   ONLY ON A ROW THAT HAS A CHIP, so a row with no delta keeps layer 1's own
   template untouched. AND ONLY ON .ig-slot: a footer row is not that grid, so
   naming it here would set a column template on a box that has none. */
.ig-workspace .ig-slot[data-ig-delta] {
  grid-template-columns: var(--ig-rank-column) 1fr auto;
}

/* A FOOTER ROW IS A FLEX BOX, NOT THE THREE-COLUMN GRID.

   A ranked row reaches the trailing edge by the column template above. An
   excluded or tracker-held row is layer 1's .ig-footer-row — display:flex —
   so a chip appended to it simply follows the content it was appended after,
   and the frame puts it at the row's end. An auto inline margin is the flex
   idiom for that, and it is the right tool HERE for the same reason it was the
   wrong one on the grid: it moves an item within its line, and on the grid the
   item was in the wrong line to begin with. */
.ig-workspace .ig-footer-row > .ig-delta-chip[data-placed] {
  margin-inline-start: auto;
}

/* §17c's "write landed · order computing": the PREVIOUS order, held still and
   greyed one step, with the label saying why.

   THE SAME HUE-TOKEN BLOCK, for the reason reevaluate/styles.ts gives where it
   greys .ig-reevaluate[data-order='held'] .ig-viewer: layer 1 sets color
   directly on its own descendants, so an inherited colour greys almost
   nothing, and a list of descendants to override goes stale the first time
   layer 1 colours something new. Redefined hue tokens inherit, and greying by
   colour keeps the rail's text at its theme's contrast.

   SCOPED TO THE RAIL ZONE, WHICH THE STANDALONE SURFACE DID NOT HAVE TO BE.
   There, .ig-viewer is the rail and nothing else. The workspace draws a SECOND
   viewer in the canvas zone, and greying that one is not a smaller version of
   the same idea — it is the opposite of what the held state means. What is
   stale is the ORDER; the canvas is drawing the write states #164 put there,
   and pending, failed and conflict are told partly in hue. So an in-flight edit
   would have stripped the colour channel off the very marks that say an edit is
   in flight. The rail is the only surface whose ranks the store cannot vouch
   for, so it is the only one greyed. */
.ig-workspace[data-order='held'] .ig-zone[data-zone='rail'] .ig-viewer {
  --ig-accent: var(--ig-text-muted);
  --ig-link: var(--ig-text-muted);
  --ig-link-hover: var(--ig-text-muted);
  --ig-focus: var(--ig-text-muted);
  --ig-station-ready: var(--ig-text-muted);
  --ig-station-pending: var(--ig-text-muted);
  --ig-station-held: var(--ig-text-muted);
  --ig-edge-blocked-by: var(--ig-text-muted);
  --ig-edge-serialize-with: var(--ig-text-muted);
  --ig-edge-together-with: var(--ig-text-muted);
  --ig-edge-duplicate-of: var(--ig-text-muted);
  --ig-edge-decomposed-from: var(--ig-text-muted);
  --ig-state-invalid: var(--ig-text-muted);
  --ig-state-failed: var(--ig-text-muted);
  --ig-state-conflict: var(--ig-text-muted);
  --ig-state-failed-fill: var(--ig-text-muted);
  --ig-state-failed-mark: var(--ig-text-muted);
  --ig-state-conflict-mark: var(--ig-text-muted);
  --ig-state-conflict-fill: var(--ig-text-muted);
  --ig-state-progress: var(--ig-text-muted);
}

/* ── 17k's OTHER TWO LAYOUTS ───────────────────────────────────────────────

   ONE RULE GENERATES ALL THREE, and it is the sentence 17k states outright:
   THE RAIL NEVER YIELDS. THE CANVAS YIELDS FIRST. THE INSPECTOR YIELDS IN
   BETWEEN. Because the canvas is already the zone designed to refuse (17f) and
   the inspector is the edit path that survives without it (17b).

       at or above 1138   336 / 1fr / 320, three zones (two with nothing
                          selected)
       800 - 1137         with a selection the order folds into a strip and
                          opens as a panel over the graph (#313)
       below 800          the canvas folds into a strip that opens on demand;
                          the order is 336 again

       below 640          one view at a time, picked from three tabs: the
                          order, the selection's Related groups, or the
                          Sub-issues tree; the inspector is not drawn

   THE ORDER IS 336 WHEREVER IT IS A ZONE. Folded, it is a strip and a panel of
   the same 336; it never shrinks to keep a three-column template alive.

   WHY THESE ARE RANGE CONDITIONS AND NOT max-width/min-width PAIRS. A
   container's inline size is NOT AN INTEGER. Written as (min-width: 1138px)
   and (max-width: 1137px), a box measured at 1137.5 satisfies NEITHER — so the
   base fallback comes back, and
   the one rule 17k states outright is broken at exactly the widths a resize
   drags through. The same hole sits at 799.5. 'width < 1138' and
   'width >= 1138' are complements with nothing between them, which is the
   property the layouts need and the only reason the syntax changed.

   THE BASE STAYS THE THREE-ZONE TEMPLATE, because a surface rendered WITHOUT a
   mount has no container at all and no query fires: base-is-narrow would hand
   a static page a collapsed canvas with a control nothing is listening to. So
   the wide layout is the floor and the narrow ones are carved off it, widest
   first.

   THESE SIT AT THE FOOT OF THE SHEET, WHICH IS LOAD-BEARING TWICE. The narrow
   block must come after the middle one to win where both match; and the zones'
   own rules have to come first, or a regex looking for the rule that defines
   .ig-zone[data-zone='inspector'] finds an override instead. That hazard is
   recorded further up this sheet and has already bitten once in layer 1.

   NEITHER LAYOUT IS THE STYLESHEET'S ALONE. The lifted inspector opens on
   selection and dismisses on Escape, and the strip opens on a press — so
   host.ts holds two fields and render.ts publishes them on the surface
   root as data-canvas and data-inspector. What is NOT in the host is the
   width: nothing in the package asks how wide it is, per 17k's own note that
   a package which reads the window cannot be dropped into someone else's
   settings page. Each attribute is read only by the block that has a use for
   it, and means nothing at the other widths. */

/* 17k's STRIP CONTROL, RENDERED ALWAYS AND DRAWN ONLY WHEN NARROW.
   render.ts cannot know its own width, so the button is always in the
   markup and this is what keeps it off the other two layouts — display:none
   rather than visibility, so it is not a tab stop where it has nothing to do.
   The two narrow states size it themselves, below. */
.ig-workspace .ig-canvas-strip {
  display: none;
  box-sizing: border-box;
  border: var(--ig-stroke) solid var(--ig-line);
  background: var(--ig-surface);
  color: var(--ig-text-body);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  padding: var(--ig-space-tight);
  cursor: pointer;
}

.ig-workspace .ig-canvas-strip:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

/* THE TABS AND THE RELATED GROUPS LIST, DRAWN ONLY UNDER 640, on the strip's
   reasoning above: render.ts cannot know its width, so the tabs are always in
   the markup and the list is in it whenever its tab is selected, and this is
   what keeps both off the three wider layouts. The block at the foot of the
   sheet draws them. */
/* THE DESIGN'S TABS PART: FILLED, NOT BORDERED. An idle tab is muted text on
   no fill; hover takes the secondary fill (--ig-surface-2) with full text; the selected tab
   takes the strong fill (--ig-surface) with full text. 32 tall, 12 inline
   padding, the control radius, 4 apart. The package has no 32 or 4 token, so
   both are written from the spacing scale: 2 x --ig-space-loose and
   2 x --ig-space-micro. */
.ig-workspace .ig-narrow-tabs {
  display: none;
  gap: calc(var(--ig-space-micro) * 2);
  padding: var(--ig-space-tight) var(--ig-space);
  border-bottom: var(--ig-hairline-width) solid var(--ig-hairline);
}

.ig-workspace .ig-narrow-tab {
  flex: 1;
  min-block-size: calc(var(--ig-space-loose) * 2);
  border: 0;
  border-radius: var(--ig-radius);
  background: none;
  color: var(--ig-text-muted);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  padding: 0 var(--ig-space);
  cursor: pointer;
}

.ig-workspace .ig-narrow-tab:hover {
  background: var(--ig-surface-2);
  color: var(--ig-text);
}

.ig-workspace .ig-narrow-tab[aria-selected='true'] {
  background: var(--ig-surface);
  color: var(--ig-text);
}

.ig-workspace .ig-narrow-tab:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

/* THE MIDDLE ZONE'S SWITCH, THE DESIGN'S SEGMENTED CONTROL. A filled track
   (--ig-surface-2) 32 tall with 2 of padding and 2 between its options; an idle
   option is muted text on no fill, the pressed one takes --ig-surface with full
   text at the medium weight. The option's radius is the track's less its
   padding, so the two corners stay concentric. The 32 is 2 x --ig-space-loose,
   as for the tabs above. Drawn at 640 and wider; the narrow block hides it. */
.ig-workspace .ig-canvas-switch {
  display: inline-flex;
  flex: none;
  align-items: stretch;
  gap: var(--ig-space-micro);
  block-size: calc(var(--ig-space-loose) * 2);
  box-sizing: border-box;
  padding: var(--ig-space-micro);
  border-radius: var(--ig-radius);
  background: var(--ig-surface-2);
}

.ig-workspace .ig-canvas-switch-option {
  display: inline-flex;
  align-items: center;
  border: 0;
  border-radius: calc(var(--ig-radius) - var(--ig-space-micro));
  background: none;
  color: var(--ig-text-muted);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  padding: 0 var(--ig-space);
  white-space: nowrap;
  cursor: pointer;
}

.ig-workspace .ig-canvas-switch-option[aria-pressed='true'] {
  background: var(--ig-surface);
  color: var(--ig-text);
  font-weight: var(--ig-weight-medium);
}

.ig-workspace .ig-canvas-switch-option:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-micro);
}

/* THE INSPECTOR'S GROUPS, WITH THE ORDER'S ROWS: each kind's head and count,
   its first five neighbours as layer 1 draws an order row, then "Show 4 more".
   Only the gap between the groups is this list's. Drawn by the narrow sheet,
   and past the graph's budget at every width (below). */
.ig-workspace .ig-related {
  display: none;
  flex-direction: column;
}

/* EACH HEAD IS THE BOARD'S .ig-sub (q348): 40 tall, 16 inset, a hairline
   between the groups, the words medium and the count regular. The list is
   full-bleed, so the head's inset is the only inset; the first head, "Around
   #N", has no line over it. 40 is 5 x --ig-space-snug, 12 between its parts. */
.ig-related .ig-relationship-group-head {
  min-block-size: calc(var(--ig-space-snug) * 5);
  padding: 0 var(--ig-space-loose);
  gap: var(--ig-space);
  border-top: var(--ig-hairline-width) solid var(--ig-hairline);
}

.ig-related > .ig-relationship-group-head:first-child {
  border-top: 0;
}

.ig-related .ig-relationship-count {
  font-weight: var(--ig-weight-regular);
}

/* THE FOLD AND THE EMPTY SENTENCES TAKE THE HEAD'S INSET, since the list has none of its own. */
.ig-related .ig-relationship-more,
.ig-related .ig-related-empty {
  margin-inline: var(--ig-space-loose);
}

/* The list's own sentences, the empty states: muted, at the size of the
   group counts. */
.ig-related-empty {
  margin-block: var(--ig-space);
  color: var(--ig-text-muted);
  font-size: var(--ig-font-size-small);
}

/* PAST THE GRAPH'S BUDGET AROUND THE SELECTION THE LIST STANDS IN FOR THE
   GRAPH, AT EVERY WIDTH (RULES, Graphs, Dense neighbourhoods): the graph is
   not drawn, so the list is the zone's content wherever the zone is. */
.ig-workspace .ig-related[data-over='true'] {
  display: flex;
}

/* THE ONE LINE OVER IT THAT SAYS WHY, the board's .ig-over: small muted text
   with a hairline under it, at the zone's inset. Under 640 it is hidden with
   the rest of the graph's zone, since there the list is the view as always. */
.ig-related-over {
  margin: 0;
  padding: var(--ig-space) var(--ig-space-loose);
  color: var(--ig-text-muted);
  font-size: var(--ig-font-size-small);
  border-bottom: var(--ig-hairline-width) solid var(--ig-hairline);
}

/* A KIND'S HEAD IN THE LIST: its icon beside its words, as one phrase. The
   head's muted colour and weight are the group head's. */
.ig-related-kind {
  display: inline-flex;
  align-items: baseline;
  gap: var(--ig-space-snug);
}

/* ONE KEY PER SURFACE, AND THE CANVAS KEEPS IT.

   Both zones hold a viewer, so both draw the grammar legend, and this surface
   showed the same five line styles twice side by side at the same moment. It is
   the defect chrome: false already answers one line higher — §16's panel has
   ONE header — and render.ts records the reasoning for which zone yields:
   four of the five entries are LINE styles and the rail draws no lines, only
   badges, so the key belongs beside the strokes it is about. It is the cheaper
   zone to spend it in, too: one or two wrapped rows of a wide column against
   four rows of a 336 rail the order needs.

   REACHING A VIEWER CLASS, FROM INSIDE THIS SURFACE'S OWN ROOT, FOR A STATE
   THAT PACKAGE DOES NOT MODEL — which is the exemption reevaluate/styles.ts
   already states and uses for the greyed rail. The viewer cannot answer this:
   each instance is correct on its own and the duplication only exists in the
   composition, which is this package's. Nothing here changes how a legend looks
   anywhere else, and the markup is untouched — the rail still RENDERS its key,
   so the two rules below can hand it back without re-rendering anything. */
.ig-workspace[data-canvas-legend='drawn'] .ig-zone[data-zone='rail'] .ig-legend {
  display: none;
}

/* THE ORDER'S STRIP AND THE PANEL'S HEAD exist only while the order is folded
   (#313); every layout but the folded one leaves them out. The strip's head is
   48 tall like a zone head, with one centred 32 ghost icon button. */
.ig-order-strip {
  display: none;
  flex-direction: column;
  border-right: var(--ig-hairline-width) solid var(--ig-hairline);
}

/* The strip's 48 head, ruled where the panel's head and the graph's toolbar
   are ruled, so the hairlines meet across the fold. */
.ig-order-strip-head {
  display: flex;
  justify-content: center;
  align-items: center;
  min-block-size: calc(var(--ig-space-loose) * 3);
  border-bottom: var(--ig-hairline-width) solid var(--ig-hairline);
}

.ig-order-toggle,
.ig-order-close,
.ig-sheet-close {
  display: inline-grid;
  place-items: center;
  inline-size: calc(var(--ig-space-loose) * 2);
  block-size: calc(var(--ig-space-loose) * 2);
  padding: 0;
  border: 0;
  border-radius: var(--ig-radius);
  background: none;
  color: var(--ig-text-muted);
  cursor: pointer;
}

.ig-order-toggle:hover,
.ig-order-close:hover,
.ig-sheet-close:hover,
.ig-order-toggle[aria-expanded='true'] {
  background: var(--ig-surface-2);
  color: var(--ig-text);
}

.ig-order-toggle:focus-visible,
.ig-order-close:focus-visible,
.ig-sheet-close:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-micro);
}

/* THE ORDER ZONE'S HEAD AT EVERY WIDTH (#330, RULES Graphs: each zone has a
   48 head with its title and counts): "Work order", "16 ranked · 2 at a
   time". Its close button belongs to the folded panel alone, so it shows only
   there (the fold block below). */
.ig-order-head {
  display: flex;
  align-items: center;
  gap: var(--ig-space-snug);
  min-block-size: calc(var(--ig-space-loose) * 3);
  padding: 0 var(--ig-space-loose);
  border-bottom: var(--ig-hairline-width) solid var(--ig-hairline);
}

.ig-order-title {
  margin: 0;
  font-size: inherit;
  font-weight: var(--ig-weight-medium);
}

.ig-order-count {
  color: var(--ig-text-muted);
  font-variant-numeric: tabular-nums;
}

.ig-order-head .ig-order-close {
  display: none;
  margin-inline-start: auto;
}

/* THE INSPECTOR SHEET'S CLOSE CONTROL (#245). Every render draws it in the
   Inspector's zone; it shows only under 640 while the Inspector is a sheet
   (the phone block below), and nowhere else is there a sheet to close. */
.ig-sheet-close {
  display: none;
}

/* THE ORDER FOLDS (#313, Claude Design 7b8fcbc, RULES "The workspace").

   THE BOARD'S ZONES: the order 336, the graph at least 480, the Inspector 320,
   fixed in px (ZONE_WIDTHS, issue 253) so a theme's character width cannot
   move them. Narrower than the three with their hairlines (ZONES_FIT, 1138),
   and with something selected, the order folds into
   a 40 strip so the graph keeps its room and nothing runs under the
   Inspector: 40 | minmax(0, 1fr) | 320. The strip holds one button, "Show the
   work order", which opens the order over the graph as a panel 336 wide; a
   pick, Escape or the panel's close button closes it. With nothing selected
   (or the Inspector dismissed) nothing folds: the order at 336, the graph
   takes the rest, and no Inspector is drawn.

   THE PANEL IS PLACED IN THE CANVAS'S GRID AREA, at its start, not positioned
   by an offset: the strip is a different area, so the panel begins at the
   strip's edge however the tracks change. */
@container ig-workspace (width < 1138px) {
  .ig-workspace {
    grid-template-areas:
      'header header'
      'rail canvas';
    grid-template-columns:
      336px
      1fr;
  }
  .ig-workspace .ig-zone[data-zone='inspector'] {
    display: none;
  }
  .ig-workspace[data-inspector='lifted'] {
    grid-template-areas:
      'header header header'
      'rail canvas inspector';
    grid-template-columns:
      calc(var(--ig-space-wide) * 2)
      minmax(0, 1fr)
      320px;
  }
  .ig-workspace[data-inspector='lifted'] .ig-zone[data-zone='inspector'] {
    display: block;
    grid-area: inspector;
  }
  .ig-workspace[data-inspector='lifted'] .ig-order-strip {
    display: flex;
    grid-area: rail;
  }
  .ig-workspace[data-inspector='lifted'] .ig-zone[data-zone='rail'] {
    display: none;
  }
  .ig-workspace[data-inspector='lifted'][data-order-panel='open'] .ig-zone[data-zone='rail'] {
    display: block;
    grid-area: canvas;
    justify-self: start;
    inline-size: 336px;
    z-index: 2;
    /* ON THE CARD, OPAQUE (#340): see the audit overlay's note. */
    background: var(--ig-bg);
    box-shadow: var(--ig-elevation-overlay);
  }
  .ig-workspace[data-inspector='lifted'][data-order-panel='open'] .ig-order-close {
    display: inline-grid;
  }
  /* NO INSPECTOR ON SCREEN, SO THE LOG KEEPS THE CARD. */
  .ig-workspace[data-inspector='dismissed'] .ig-log-recovery[data-ig-inspected] {
    display: flex;
  }
}

/* THE NARROW LAYOUT: the canvas collapses, the inspector comes back inline,
   and the rail still does not move.

   THE INSPECTOR IS RESTORED DECLARATION BY DECLARATION rather than by scoping
   the block above to a band, because the sheet's guard has no band to scope to.
   Each line here answers one line there, on the same selector so source order
   settles it — that is the price of single-sided conditions, paid in full and
   in one place.

   THE STRIP IS 40 WIDE. The canvas is the zone designed to refuse (17f), so
   what it yields is everything except the handle that brings it back; the
   inspector takes 1fr, which at 799 is about 420, above the 320 the wide layout
   gives it, so the zone that yields in between is not yielding here at all.
   That is the order the rule names. */
@container ig-workspace (width < 800px) {
  /* THE RAIL TAKES THE KEY BACK, BECAUSE THERE IS NO CANVAS TO CARRY IT. Below
     this width §17k collapses the canvas to a four-character strip, so the zone
     the rule above defers to is not on screen — and the station fills the rail
     draws itself would have no key at all. display: flex rather than revert
     because that is what .ig-legend is; the value has to be restated, which is
     the price of a single-sided condition and is paid here in one place. */
  .ig-workspace[data-canvas-legend='drawn'] .ig-zone[data-zone='rail'] .ig-legend {
    display: flex;
  }

  .ig-workspace,
  .ig-workspace[data-inspector='lifted'] {
    grid-template-areas:
      'header header header'
      'rail canvas inspector';
    grid-template-columns:
      336px
      calc(var(--ig-space-wide) * 2)
      1fr;
  }
  /* THE ORDER UNFOLDS HERE: the graph is the zone that folds below 800 (#313). */
  .ig-workspace[data-inspector='lifted'] .ig-order-strip {
    display: none;
  }
  .ig-workspace[data-inspector='lifted'] .ig-zone[data-zone='rail'],
  .ig-workspace[data-inspector='lifted'][data-order-panel='open'] .ig-zone[data-zone='rail'] {
    display: block;
    grid-area: rail;
    justify-self: stretch;
    inline-size: auto;
    z-index: auto;
    background: none;
    box-shadow: none;
  }
  .ig-workspace[data-inspector='lifted'][data-order-panel='open'] .ig-order-close {
    display: none;
  }

  .ig-workspace .ig-zone[data-zone='inspector'] {
    grid-area: inspector;
    justify-self: stretch;
    inline-size: auto;
    z-index: auto;
    background: none;
    box-shadow: none;
  }

  /* THE INSPECTOR IS A COLUMN AGAIN, so the canvas has nothing to clear. */
  .ig-workspace[data-inspector='lifted'] .ig-zone[data-zone='canvas'] {
    padding-inline-end: 0;
  }

  /* THE DISMISSAL MEANS NOTHING HERE, and saying so is the undo of the middle
     block's only conditional rule. The inspector is a zone again, so there is
     no overlay to have dismissed. */
  .ig-workspace[data-inspector='dismissed'] .ig-zone[data-zone='inspector'],
  .ig-workspace[data-inspector='empty'] .ig-zone[data-zone='inspector'] {
    display: block;
  }

  /* THE INSPECTOR IS BACK, SO THE LOG'S COPY STANDS DOWN AGAIN. */
  .ig-workspace[data-inspector='dismissed'] .ig-log-recovery[data-ig-inspected] {
    display: none;
  }

  .ig-workspace[data-canvas='strip'] .ig-canvas-strip {
    display: block;
    writing-mode: vertical-rl;
    inline-size: 100%;
    block-size: 100%;
    overflow: hidden;
    white-space: nowrap;
  }

  /* COLLAPSED MEANS GONE, NOT CLIPPED. The zone is overflow:auto, so leaving
     the graph in a 31-wide track would keep every node in the tab order behind
     a scrollbar the reader cannot use — and a keyboard reader would walk a
     canvas nobody can see. display:none is what takes them out of the tree,
     and it is reversible in one attribute.

     TWO EXCEPTIONS, AND NEITHER IS THE CANVAS. The strip is the handle that
     brings the zone back. 17d's audit overlay is a sibling of the graph rather
     than part of it — it is anchored to the HEADER COUNT, which is drawn at
     every width, so a collapsed canvas taking it down would remove a surface
     the reader opened from a control that is still there. */
  .ig-workspace[data-canvas='strip']
    .ig-zone[data-zone='canvas']
    > :not(.ig-canvas-strip):not(.ig-audit-overlay) {
    display: none;
  }

  /* AND THE OVERLAY HAS TO ESCAPE THE STRIP IT HANGS OFF.

     17d positions it against the canvas ZONE, which is what keeps it off the
     rail without a magic offset. That argument still holds here and the
     ARITHMETIC does not: the zone is four characters wide, so the panel's own
     'width: min(66.67ch, 100% - gap)' resolves to the strip, and 'right' would
     anchor a wider one leftwards — across the rail, which is the one thing 17k
     says an overlay must never do.

     SO THE ANCHOR FLIPS AND THE CLAMP GOES. Anchored at the zone's leading
     edge it opens away from the rail, into the room the inspector is using —
     over it, which is what an overlay is for. The zone stops clipping while it
     is a strip, which costs nothing: every other child is display:none above,
     so there is nothing else left to spill.

     MEASURED at a 1000 mount: the zone's leading edge is 419, the rail ends at
     407, and 520 of panel fits in the 598 that remains. Below about 900 it
     runs past the trailing edge, which is the band 17k already hands to
     section 9. */
  .ig-workspace[data-canvas='strip'] .ig-zone[data-zone='canvas'] {
    overflow: visible;
  }

  .ig-workspace[data-canvas='strip'] > .ig-audit-overlay {
    left: 0;
    right: auto;
    width: calc(var(--ig-char-width) * 66.67);
    max-height: 100%;
    /* THE SHADOW GOES WITH THE CLIPPING, and that pairing is the whole point.
       Section 3 forbids this panel reaching the rail ABSOLUTELY, and it is a
       rule about what a reader SEES — a soft edge falling across the order
       breaks it exactly as a border would. Everywhere else the zone's own
       overflow is what guarantees that; here the zone is deliberately not
       clipping, so the one thing that could paint outside the border box is
       removed instead. The panel still reads as raised: it keeps its ground
       and its border, over a canvas that is four characters wide and drawing
       nothing. */
    box-shadow: none;
  }

  /* OPENED FULL-WIDTH ON DEMAND — 17k's words — and full-width is measured
     from the rail, which still does not yield. The inspector stands down while
     it is open, which is the one place this layout borrows from the middle
     one: the canvas is transient here in the way the panel is there. */
  .ig-workspace[data-canvas='open'] {
    grid-template-areas:
      'header header'
      'rail canvas';
    grid-template-columns:
      336px
      1fr;
  }

  .ig-workspace[data-canvas='open'] .ig-zone[data-zone='inspector'] {
    display: none;
  }

  /* The same control closes it, so it stops being a strip and reads as a
     button above the canvas it opened. */
  .ig-workspace[data-canvas='open'] .ig-canvas-strip {
    display: block;
    justify-self: start;
  }
}

/* THE PHONE LAYOUT: one view at a time, under the tabs.

   THE TAB IS THE ROOT'S data-tab, which render.ts derives from the host's
   narrowView and canvas mode. The rail and the canvas zone share one grid
   area, and the tab decides which of them is drawn in it. The inspector is not
   drawn at this width.

   THE TWO BLOCKS ABOVE ALSO MATCH HERE, because every condition in this sheet
   is single-sided, so each of their rules this layout disagrees with is
   answered below on a selector at least as specific, and source order settles
   it. That includes the collapsed and opened canvas: neither means anything
   when the canvas is a whole tab. */
@container ig-workspace (width < 640px) {
  .ig-workspace {
    grid-template-areas:
      'header'
      'audit'
      'tabs'
      'view';
    grid-template-rows: auto auto auto 1fr;
    grid-template-columns: 1fr;
  }

  .ig-workspace[data-canvas='open'] {
    grid-template-areas:
      'header'
      'audit'
      'tabs'
      'view';
    grid-template-rows: auto auto auto 1fr;
    grid-template-columns: 1fr;
  }

  .ig-workspace .ig-zone[data-zone='rail'],
  .ig-workspace .ig-zone[data-zone='canvas'] {
    grid-area: view;
  }

  /* ONE VIEW AT A TIME, whatever the wider layouts did with a selection: the
     order is a tab here, never a strip or a panel (#313). */
  .ig-workspace[data-inspector='lifted'],
  .ig-workspace[data-inspector='lifted'][data-canvas='open'] {
    grid-template-areas:
      'header'
      'audit'
      'tabs'
      'view';
    grid-template-rows: auto auto auto 1fr;
    grid-template-columns: 1fr;
  }
  .ig-workspace[data-inspector='lifted'] .ig-zone[data-zone='rail'],
  .ig-workspace[data-inspector='lifted'][data-order-panel='open'] .ig-zone[data-zone='rail'] {
    grid-area: view;
  }

  .ig-workspace .ig-zone[data-zone='rail'] {
    border-right: 0;
  }

  .ig-workspace .ig-narrow-tabs {
    display: flex;
  }

  /* THE NARROW TABS CARRY THE SWITCH'S CHOICE HERE, so the switch is not drawn. */
  .ig-workspace .ig-canvas-switch {
    display: none;
  }

  /* Every value of data-inspector, so the narrow block's 'dismissed' restore
     and the middle block's lifted panel are both answered. */
  .ig-workspace[data-inspector] .ig-zone[data-zone='inspector'] {
    display: none;
  }

  /* A SELECTION LIFTS THE INSPECTOR AS A SHEET FROM THE BOTTOM (#245, the
     design rule "the Inspector is a Sheet from the bottom"). There is no
     column for it here, so it rises over the tab the reader is on: it takes
     the view's area, sits on that area's bottom edge and is never taller than
     the view. It is the Sheet part (RULES, Sheet: card fill, overlay shadow,
     from the bottom): the card's fill and its large radius on the two top
     corners, so it reads as lifted over the panel rather than as more of it.
     The tabs stay above it, so the reader can still change tab. Escape and
     the close control both send narrow-dismiss, which makes data-inspector
     'dismissed' and this rule stop matching. */
  .ig-workspace[data-inspector='lifted'] .ig-zone[data-zone='inspector'] {
    display: block;
    grid-area: view;
    align-self: end;
    justify-self: stretch;
    inline-size: auto;
    max-block-size: 100%;
    z-index: 2;
    background: var(--ig-surface);
    border-left: 0;
    border-start-start-radius: var(--ig-radius-large);
    border-start-end-radius: var(--ig-radius-large);
    box-shadow: var(--ig-elevation-overlay);
  }

  /* CLOSE AT THE HEAD ROW'S END, beside the title (the board). The row is
     space-between, so the auto margin on the control before it takes the free
     space and the two sit together at the end. */
  .ig-workspace[data-inspector='lifted'] .ig-sheet-close {
    display: inline-grid;
  }

  .ig-workspace[data-inspector='lifted'] .ig-inspector-head > .ig-inspector-clear {
    margin-inline-start: auto;
  }

  /* NO INSPECTOR HERE AT ALL, SO THE LOG KEEPS EVERY CARD. Every value of
     data-inspector, so it outranks the narrow block's rule above. */
  .ig-workspace[data-inspector] .ig-log-recovery[data-ig-inspected] {
    display: flex;
  }

  .ig-workspace[data-tab='related'] .ig-zone[data-zone='rail'],
  .ig-workspace[data-tab='sub-issues'] .ig-zone[data-zone='rail'],
  .ig-workspace[data-tab='related'][data-order-panel='open'] .ig-zone[data-zone='rail'],
  .ig-workspace[data-tab='sub-issues'][data-order-panel='open'] .ig-zone[data-zone='rail'] {
    display: none;
  }

  /* THE ORDER TAB HIDES THE CANVAS ZONE. visibility rather than display, so a
     hidden box is out of hit testing, the tab order and the accessibility tree
     while the zone keeps its place in the grid. The problems panel in it is
     the one exception, and it is drawn IN FLOW, at the end of this block. */
  .ig-workspace[data-tab='order'] .ig-zone[data-zone='canvas'] {
    visibility: hidden;
  }

  /* THE ORDER'S KEY IS ITS READINESS KEY, AT THE END OF THE LIST (issue 296).
     Docked, the rail's legend stuck to the bottom of a phone's short view and,
     wrapping its five relationships and four readiness keys onto many lines,
     left room for about two rows of the order. The export's list ends with a
     readiness key, and its rows print each relationship's words beside its
     icon, so here the bar scrolls with the list and keeps the readiness key
     alone. */
  .ig-workspace .ig-zone[data-zone='rail'] .ig-viewer[data-legend='docked'] > .ig-legend {
    position: static;
  }

  .ig-workspace .ig-zone[data-zone='rail'] .ig-legend > .ig-legend-item {
    display: none;
  }

  /* NO STRIP: the tabs are the way to the canvas here. */
  .ig-workspace[data-canvas] .ig-canvas-strip {
    display: none;
  }

  /* THE COLLAPSED CANVAS IS UNDONE, rule by rule. The narrow block hides every
     child of the zone but the strip and the audit overlay, lets the zone spill
     and re-anchors the overlay to its leading edge. On the Sub-issues tab the
     zone's children are drawn again — the tree, the isolated list and the
     toolbar, which is a flex row; the ':not' on the toolbar's rule only lifts
     it to the specificity of the rule before it. */
  .ig-workspace[data-tab='sub-issues'][data-canvas='strip']
    .ig-zone[data-zone='canvas']
    > :not(.ig-canvas-strip):not(.ig-audit-overlay) {
    display: block;
  }

  .ig-workspace[data-tab='sub-issues'][data-canvas='strip']
    .ig-zone[data-zone='canvas']
    > .ig-canvas-toolbar:not(.ig-audit-overlay) {
    display: flex;
  }

  /* A TOOLBAR HOLDING NOTHING BUT THE HIDDEN SWITCH would be an empty bordered
     band. The second selector matches the Sub-issues rule above, which shows
     the toolbar on a collapsed canvas, and wins by coming after it. */
  .ig-workspace .ig-zone[data-zone='canvas'] > .ig-canvas-toolbar:not(:has(> :not(.ig-canvas-switch))),
  .ig-workspace[data-tab='sub-issues'][data-canvas='strip']
    .ig-zone[data-zone='canvas']
    > .ig-canvas-toolbar:not(:has(> :not(.ig-canvas-switch))) {
    display: none;
  }

  .ig-workspace[data-canvas='strip'] .ig-zone[data-zone='canvas'] {
    overflow: auto;
  }


  /* RELATED GROUPS SHOWS ONLY ITS LIST. The graph beneath it is the wide
     layouts' view of the same relationships, and a line needs two columns. The
     audit overlay is the exception, as it is in the collapsed canvas. */
  .ig-workspace[data-tab='related'] .ig-zone[data-zone='canvas'] > :not(.ig-related):not(.ig-audit-overlay) {
    display: none;
  }

  .ig-workspace[data-tab='related'][data-canvas] .ig-zone[data-zone='canvas'] > .ig-related {
    display: flex;
  }

  /* WITH NOTHING SELECTED THE TAB IS THE GROUPS, never every issue at once
     (RULES, Graphs, Dense neighbourhoods). The render leaves the list out and
     the cards the ladder drew stand in its place, so each group is one control
     whatever the width. */
  .ig-workspace[data-tab='related'][data-canvas]
    .ig-zone[data-zone='canvas']:not(:has(> .ig-related))
    > .ig-ladder {
    display: flex;
  }

  /* PROBLEMS TO FIX OPENS IN THE FLOW UNDER THE HEAD, ON EVERY TAB (issue 334,
     Design 6b8a53e "Under 640: Problems to fix opens in the flow under the
     head"). Between the head and the Tabs, full width, on the page's ground:
     no fill of its own, a hairline under it, no radius, no shadow; the panel's
     own padding is the gutter. The order and the graph are pushed down, never
     covered, and the over-the-graph overlay is gone at this width. Its own
     row in the grid ('audit'), which is empty while the panel is shut.
     [data-canvas] so it outranks the strip layout's placement above. */
  .ig-workspace[data-canvas] > .ig-audit-overlay {
    grid-area: audit;
    position: static;
    width: auto;
    max-height: none;
    overflow: visible;
    background: none;
    border: 0;
    border-bottom: var(--ig-hairline-width) solid var(--ig-hairline);
    border-radius: 0;
    box-shadow: none;
  }

  .ig-workspace[data-canvas] > .ig-audit-overlay .ig-audit-panel {
    border-bottom: 0;
  }

  .ig-workspace .ig-narrow-tabs {
    grid-area: tabs;
  }
}


.ig-picker {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  line-height: var(--ig-line-height);
  color: var(--ig-text-body);
}

.ig-picker-heading {
  margin: 0;
  font-weight: normal;
  font-size: var(--ig-font-size-small);
  color: var(--ig-text-muted);
}

.ig-picker-kinds {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

.ig-picker-choice {
  display: flex;
  align-items: baseline;
  gap: var(--ig-space-tight);
  width: 100%;
  text-align: left;
  background: var(--ig-surface);
  color: var(--ig-text-body);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight);
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
}

.ig-picker-choice:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-stroke);
}

/* The kind the edge already carries. Marked on the ROW rather than on the
   button, so a host restyling the control keeps the distinction. */
.ig-picker-kind[data-current='true'] .ig-picker-choice {
  background: var(--ig-surface-2);
  border-color: var(--ig-accent);
  color: var(--ig-text);
}

.ig-picker-current {
  margin-left: auto;
  font-size: var(--ig-font-size-small);
  color: var(--ig-text-muted);
}


.ig-firstpass {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  line-height: var(--ig-line-height);
  color: var(--ig-text-body);
  background: var(--ig-surface);
  border-radius: var(--ig-radius);
  padding: var(--ig-space);
}

.ig-firstpass-question {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

.ig-firstpass-statement {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--ig-space-tight);
  margin: 0;
  color: var(--ig-text);
}

.ig-firstpass-ref {
  font-family: var(--ig-font-mono);
}

.ig-firstpass-kind {
  font-family: var(--ig-font-mono);
  color: var(--ig-text-muted);
}

.ig-firstpass-evidence {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
  border-left: var(--ig-stroke) solid var(--ig-line);
  padding-left: var(--ig-space);
}

.ig-firstpass-evidence-label {
  margin: 0;
  font-size: var(--ig-font-size-small);
  color: var(--ig-text-muted);
}

.ig-firstpass-evidence-list {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
  margin: 0;
  padding: 0;
  list-style: none;
}

.ig-firstpass-evidence-item {
  font-size: var(--ig-font-size-small);
  color: var(--ig-text-body);
}

.ig-firstpass-answers {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ig-space-tight);
}

.ig-firstpass-answer,
.ig-firstpass-undo {
  font: inherit;
  color: var(--ig-text);
  background: var(--ig-surface-2);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight) var(--ig-space);
  cursor: pointer;
}

/* The one answer that writes. Weighted so the irreversible option is the one
   the eye lands on — §17e's consent rule is about knowing what you agreed to,
   and that starts before the keystroke. */
.ig-firstpass-answer[data-ig-answer='apply'] {
  border-color: var(--ig-accent);
}

.ig-firstpass-undo {
  align-self: flex-start;
  color: var(--ig-text-muted);
}

.ig-firstpass-answer:focus-visible,
.ig-firstpass-undo:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-stroke);
}

.ig-firstpass-progress {
  margin: 0;
  font-size: var(--ig-font-size-small);
  color: var(--ig-text-muted);
}

.ig-firstpass-finished,
.ig-firstpass-empty {
  margin: 0;
  color: var(--ig-text);
}


.ig-mount {
  position: relative;
  height: 100%;
  min-height: 0;
}

.ig-mount > .ig-workspace {
  /* THE FLOATING CHOOSER'S BOX. A canvas drop places the kind chooser inside
     the workspace root, so a host that scopes its theme to that root still
     resolves the chooser's tokens; the root is the positioning box for it. */
  position: relative;
  height: 100%;
  box-sizing: border-box;
}

.ig-mount[data-dragging='true'] {
  cursor: grabbing;
  user-select: none;
}

.ig-chrome {
  padding: var(--ig-space-tight) var(--ig-space);
  border-top: var(--ig-stroke) solid var(--ig-line);
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  line-height: var(--ig-line-height);
  color: var(--ig-text-body);
}

.ig-chrome-sentence {
  margin: 0;
  font-family: var(--ig-font-mono);
  color: var(--ig-text);
}

.ig-chrome-button {
  font: inherit;
  font-size: var(--ig-font-size-small);
  color: var(--ig-text);
  background: var(--ig-surface-2);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight) var(--ig-space);
  cursor: pointer;
  text-align: left;
}

.ig-chrome-button:hover {
  border-color: var(--ig-accent);
}

.ig-chrome-button:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

.ig-chrome-quiet {
  background: none;
  color: var(--ig-text-muted);
}

.ig-chrome-danger {
  color: var(--ig-state-failed);
  border-color: var(--ig-state-failed);
}

.ig-chrome-input {
  font: inherit;
  font-size: var(--ig-font-size-small);
  color: var(--ig-text);
  background: var(--ig-surface-2);
  border: var(--ig-stroke) solid var(--ig-line);
  border-radius: var(--ig-radius);
  padding: var(--ig-space-tight) var(--ig-space);
  width: 100%;
  box-sizing: border-box;
}

.ig-chrome-input:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: var(--ig-space-tight);
}

.ig-chrome-kinds {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

/* EACH KIND CARRIES ITS HUE ON THE LEFT, the same hue the viewer draws the
   edge in, so the chooser and the canvas name a relationship the same way. */
.ig-chrome-kinds .ig-chrome-button {
  border-left: var(--ig-terminal-width) solid var(--ig-line);
}

.ig-chrome-kinds [data-edge='blocked-by'] {
  border-left-color: var(--ig-edge-blocked-by);
}

.ig-chrome-kinds [data-edge='serialize-with'] {
  border-left-color: var(--ig-edge-serialize-with);
}

.ig-chrome-kinds [data-edge='together-with'] {
  border-left-color: var(--ig-edge-together-with);
}

.ig-chrome-kinds [data-edge='duplicate-of'] {
  border-left-color: var(--ig-edge-duplicate-of);
}

.ig-chrome-kinds [data-edge='decomposed-from'] {
  border-left-color: var(--ig-edge-decomposed-from);
}

.ig-chrome-matches {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

.ig-chrome-match {
  width: 100%;
}

.ig-chrome-search,
.ig-chrome-chooser {
  display: flex;
  flex-direction: column;
  gap: var(--ig-space-tight);
}

/* PLACED BY THE MOUNT, at the drop point `pickerPlacement` chose: `left` and
   `top` are written inline on the element, so this rule carries the box and
   nothing about where it sits. */
.ig-chrome-floating {
  position: absolute;
  width: calc(var(--ig-char-width) * 40);
  padding: var(--ig-space-tight) var(--ig-space);
  background: var(--ig-surface-2);
  border: var(--ig-stroke) solid var(--ig-accent);
  border-radius: var(--ig-radius);
  z-index: 2;
}

/* THE KEYS LINE UNDER THE INSPECTOR TAKES THE SMALL ROLE, IN THE SANS. It is
   a sentence the reader reads, not a key they type, so it is not mono; it is a
   hint beside the panel rather than its content, so it sits a step below the
   body, muted, with tabular figures. The face is stated rather than inherited
   so no sheet installed above this one can carry it back to mono. */
.ig-chrome-keys {
  margin: 0;
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size-small);
  font-variant-numeric: tabular-nums;
  color: var(--ig-text-muted);
}

/* THE FIRST PASS COVERS THE WORKSPACE. §17e is a review queue rather than a
   fourth column, so it is drawn over the three zones instead of beside them.
   Placed against the workspace root, which is this sheet's positioning box. */
.ig-firstpass-overlay {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: flex;
  flex-direction: column;
  align-items: center;
  /* START-SAFE, NOT CENTRED. Evidence is host prose of no fixed length, and a
     short workspace makes any panel too tall — centring overflow puts the
     question above the container's own origin, where no scroll can reach it.
     Laid out from the top and centred by the panel's own auto margins, which
     collapse the moment there is not enough room. */
  justify-content: flex-start;
  overflow: auto;
  gap: var(--ig-space);
  padding: var(--ig-space-loose);
  box-sizing: border-box;
  background: var(--ig-bg);
  font-family: var(--ig-font-ui);
  font-size: var(--ig-font-size);
  line-height: var(--ig-line-height);
  color: var(--ig-text-body);
}

/* A CONTAINER THAT TAKES FOCUS NEEDS A RING. The wrapper is focused on open and
   after every answer, so without one a sighted keyboard user cannot see where
   they are on the surface built for them. */
.ig-firstpass-overlay:focus-visible {
  outline: var(--ig-focus-ring) solid var(--ig-focus);
  outline-offset: calc(var(--ig-stroke) * -1);
}

.ig-firstpass-panel {
  width: 100%;
  max-width: calc(var(--ig-char-width) * 72);
  /* Centres while it fits, and starts at the top the moment it does not. */
  margin-block: auto;
}

/* The scanning and failed sentences. Both are the host's words. */
.ig-firstpass-note {
  margin: 0;
  color: var(--ig-text-muted);
}
